/* glossary.js — 知识搜索词条数据（共 160 条）
 * 由 ai-pm-coach-app/数据生成脚本-知识搜索-glossary.py 生成，勿手改。
 * 来源：知识库 104 条 + 补强篇 20 条（原文三段式拆分，缺段补写以 supp 字段标注）
 *       + supplement2 补遗 23 条（batch:"supplement2"，逐句切分、文本逐字来自原文）
 *       + supplement3 补遗二期 13 条（batch:"supplement3"，框架工具层 6 + 基础根条目 7，同口径）。 */
var GLOSSARY_BANK=[{"cat": "技术术语", "concept": "AI 的性能很大程度上取决于数据质量，模型是厨师、数据就是食材。数据分两类：一类是通用大模型训练用的数据，如维基百科、开源问答库，由模型厂商负责，普通 PM 基本接触不到；另一类是业务场景下的定制数据，如用户行为日志、垂类问答内容、客服对话数据，才是 PM 能真正掌控和设计的数据资产。", "id": "KB-001", "kp": 24, "kw": ["数据质量", "数据集", "数据标注", "业务数据", "合规"], "notes": "要注意隐私与合规性，确保数据集能为模型提供高质量、有代表性且无偏见的训练材料；数据来源须可靠且经过验证，外部获取的数据应严格评估；数据标注要准确，避免错误的标签影响模型的学习过程。", "supp": [], "term": "数据", "usage": "PM 在数据方面要能回答三个问题：手头数据质量如何，是否足够干净、丰富、代表性强；数据能从哪里来，是否合规、可获取、可用；数据能不能帮助模型在某个场景下变得更聪明、真正解决用户痛点。评价数据集可从准确性、完整性、一致性、多样性、时效性等角度入手，并分析哪些特征对模型预测最重要。"}, {"cat": "技术术语", "concept": "在传统产品中关注的是服务器资源，而在 AI 产品中算力更加核心，GPU、TPU 等芯片是所有训练和推理工作的基础。", "id": "KB-002", "kp": 15, "kw": ["算力", "GPU", "推理成本", "ROI", "量化"], "notes": "可考虑用量化、蒸馏、压缩等方法，在不牺牲效果的前提下降低成本，避免只关注效果而忽略运行成本。", "supp": [], "term": "算力", "usage": "PM 不需要掌握 CUDA 编程，但要站在投入产出比（ROI）角度思考：某个模型功能上线后需要多少推理算力、延迟能否接受；使用大模型或定制模型的运行成本预估是多少、是否能承受。这些问题不仅关乎模型是否能跑起来，更关乎产品是否具备商业闭环的基础。"}, {"cat": "技术术语", "concept": "算法是 AI 真正聪明的来源，它定义了机器处理信息的方式。虽然听上去很工程，但对 AI 产品经理来说，理解其原理与边界至关重要。", "id": "KB-003", "kp": 12, "kw": ["算法", "技术边界", "需求评估", "跨团队协作"], "notes": "不理解边界容易拍脑袋提需求、天马行空要奇迹；PM 要先分清能做与做不到，再提需求。", "supp": [], "term": "算法：AI的“大脑”逻辑", "usage": "理解算法带来两个直接好处：一是厘清技术边界，知道哪些问题是 AI 能做的、哪些是技术目前做不到的，从而有效评估需求的可实现性；二是跨团队协作更顺畅，能和算法工程师站在相同语境上沟通，明确需求。"}, {"cat": "技术术语", "concept": "大模型可想象成超级复读机加联想大师：它通过阅读互联网上几乎所有公开文字，学习词语搭配规律和上下文关系，并不真正理解知识，而是根据上半句估算并生成最可能出现的下半句，从而进行对话、写作、翻译等。其本质是文字接龙机器：预测下一个最可能出现的词，再循环预测下去，包含海量阅读、学习搭配、生成问答三个核心环节。", "id": "KB-004", "kp": 0, "kw": ["大模型", "LLM", "概率生成", "模型选型", "榜单评测", "温度参数"], "notes": "必须面对三个硬约束：它不是在思考而是在做概率计算，严密逻辑推理场景经常出错；它的知识有截止日期，之后发生的事情它不知道，问了只会编；同样输入每次输出可能不同，要想输出稳定就得调低温度参数。做 AI 产品第一步是想清楚 AI 做不了什么，把做不了的部分用规则、人工、兜底策略补上。人工评测成本高、难以规模化，自动化评测对语义、上下文、情感评估能力有限、容易误伤，两者需搭配。", "supp": [], "term": "LLM大模型 (Large Language Model, LLM)", "usage": "选型时看三点：看榜单表现，如 C-Eval、MMLU、CMMLU 等权威评估榜单，以及 SuperCLUE 等专业测评类榜单和 LMSYS Chatbot Arena 等群众投票类榜单；看训练语料来源是否涵盖目标场景、语言或知识体系；看厂商实际应用与客户分布。评价指标可包括用户满意度评分、会话终结率、用户追加提问率、人工干预率、转化率、对话平均长度等；高频任务倾向自动化评测，关键任务以人工评测为主、辅以自动化抽检。"}, {"cat": "技术术语", "concept": "预训练是打造大模型的基础教育阶段：用一个巨大的、未分类的通用文本库（如整个维基百科、新闻、网页）来训练模型，让模型学会语言的基本语法、常识和广泛的知识。这个过程不针对任何具体任务，纯粹是喂数据、学规律，目标是打造一个知识渊博的通才毛坯房，就像学生从小学到高中学习各基础学科、建立完整知识框架，但还没决定未来职业。", "id": "KB-005", "kp": 0, "kw": ["预训练", "通用文本库", "基础教育", "通才模型"], "notes": "预训练本身不针对任何具体任务，不能把通用阶段学到的广泛知识直接等同于某个具体业务场景下的可用效果。", "supp": ["usage", "notes"], "term": "预训练 (Pre-training)", "usage": "预训练产出的是通用基础模型，是后续面向具体任务进一步处理的基础；PM 理解这一阶段有助于分清通用能力与具体场景能力之间的差别。"}, {"cat": "技术术语", "concept": "微调是在预训练好的通才基础上，用特定领域、有标注的精品数据（如法律文书、医学论文、客服对话）进行精装修，将通用大模型调教成在垂直领域更专业、更精准的专家模型。与 RAG 的区别是：RAG 是给模型开卷考试，模型本身没变，只是看着资料回答；微调是真的让模型学会了，模型参数被改了，行为模式会发生变化。LoRA 是省钱方案，只训练原始模型 0.1%-1% 的参数，效果接近全参微调但成本降 90%。", "id": "KB-006", "kp": 2, "kw": ["微调", "Fine-tuning", "LoRA", "领域数据", "参数"], "notes": "微调成本比 RAG 高一个量级，贵在三处：数据准备需要人工整理和质检高质量问答对，几千到几万条；训练需要 GPU 算力，一次训练费用几千到几万；业务规则变了得重新训练，不像 RAG 更新文档就行。别上来就想微调，大部分场景用不着，按决策路径走能省掉 90% 不必要的成本。", "supp": [], "term": "Fine-tuning  微调", "usage": "三种情况该用微调：需要特定的输出风格或语气、Prompt 怎么写都约束不住；需要模型学会自己定义的分类体系、标准和通用标准不一样；Prompt Engineering 已经调到天花板、加再多示例也没法提升效果。决策路径是先试 Prompt Engineering，效果不够加 RAG，RAG 到顶了再上微调。"}, {"cat": "技术术语", "concept": "幻觉是大模型一本正经地胡说八道的现象。由于模型基于统计概率生成文本而不是进行事实核查，当它遇到知识盲区或被模糊提示诱导时，会自信地生成逻辑自洽但完全错误或虚构的内容。它追求的是听起来合理，而不是保持真实；这种编造不是 Bug，而是大模型概率预测机制的必然结果——它不知道什么是事实，只知道什么词经常一起出现。", "id": "KB-007", "kp": 0, "kw": ["幻觉", "Hallucination", "事实核查", "RAG接地", "Bad Case"], "notes": "主流模型在事实性问答场景下的幻觉率大概在 10%-30% 之间，没有 RAG 接地的场景下会更高；幻觉无法根治，因为生成机制就是预测最可能的下一个 Token，只基于训练数据中的统计规律，不关心对业务是否正确。别拿 Demo 效果当真，Demo 里问的都是模型擅长的问题，线上用户会问各种想不到的东西。", "supp": [], "term": "Hallucination 幻觉", "usage": "产品防范三条路：RAG 接地，让模型基于真实文档回答而不是凭记忆编；输出校验，模型输出后做二次检查，比如数字和规则是否匹配；信任度设计，标注信息来源，低置信度转人工，让用户知道哪些有依据、哪些不确定。上线前必须做大规模 Bad Case 测试。"}, {"cat": "技术术语", "concept": "深度学习是一种让计算机模仿人脑神经网络进行学习的技术。它包含很多层神经元，每一层都能自动从数据中提取不同复杂度的特征，比如从像素到边缘，再到猫耳朵的轮廓。给它大量带标签的数据，它就能自己摸索出识别规律，不用手动编程具体的识别规则。", "id": "KB-008", "kp": null, "kw": ["深度学习", "神经网络", "特征提取", "带标签数据"], "notes": "使用这类能力时要注意，它依赖大量带标签的数据来自己摸索规律，数据不足或标注有问题会直接影响它学到的规律是否可靠。", "supp": ["notes"], "term": "深度学习 (Deep Learning)", "usage": "原文以教模型认猫为例：不用手动编程猫有三角形耳朵、圆眼睛等规则，而是给它看成千上万张标有猫的图片，模型自己在数据里寻找规律，下次看到新猫图就能识别。人脸识别、语音助手背后都是它在工作。"}, {"cat": "技术术语", "concept": "强化学习就像训练小狗：让一个智能体在虚拟环境里不断试错，每做一个动作，系统就给它一个奖励或惩罚作为反馈。智能体的目标是学习一套策略，让自己的每一步行动都是为了获得最终最大的累计奖励。它擅长需要连续决策和规划的任务。", "id": "KB-009", "kp": null, "kw": ["强化学习", "智能体", "奖励", "惩罚", "试错"], "notes": "运用这类方法要注意，它需要通过大量试错来学习策略，学习过程依赖奖励与惩罚反馈的设计是否合理地指向最终目标。", "supp": ["notes"], "term": "强化学习 (Reinforcement Learning)", "usage": "原文以训练玩超级玛丽的 AI 为例：AI 一开始只会瞎跳，吃到金币得奖励、撞到蘑菇受惩罚，经过无数次尝试最终学会完美通关策略。自动驾驶、围棋 AI AlphaGo 也用到了它。"}, {"cat": "技术术语", "concept": "神经网络是大模型的大脑结构。它不是树状的逻辑图，而是由无数个相互连接的神经元组成的巨大网络，每个连接都有不同的强度即权重。当输入一个词时，整个网络会被激活，这个词会和相关词语产生强弱不同的关联。模型所有的知识和能力都存储在这个网络的连接关系里，就像超级复杂的城市交通网，输入一个词如同在某个路口点亮一盏灯，能量会沿连接传到强关联的路口。", "id": "KB-010", "kp": null, "kw": ["神经网络", "神经元", "权重", "连接关系"], "notes": "使用时要注意，模型的能力来自连接关系中存储的关联，而不是一套可逐条查验的逻辑规则，不能把它当作树状逻辑图来预期其行为。", "supp": ["usage", "notes"], "term": "神经网络 (Neural Network)", "usage": "理解神经网络有助于 PM 理解大模型的思考方式：模型的思考就是不同词语节点被点亮的复杂网络图，关联强弱决定了哪些内容会被激活。"}, {"cat": "技术术语", "concept": "自监督学习是一种巧妙的学习方式，能让模型在没有人工标注的情况下，从海量数据中自己出题自己做来学习。例如把一句话里的某个词遮住让模型去猜，猜对了就调整网络让这个能力更强。这就是大模型预训练的主流方法，就像读一本没有注释的小说，通过上下文情节猜出被遮住的词并记住搭配规律。", "id": "KB-011", "kp": null, "kw": ["自监督学习", "无人工标注", "预训练", "填空预测"], "notes": "运用这类学习方式时要注意，它解决的是减少人工标注依赖的问题，学习任务是模型自己从数据中构造的填空式题目，不等同于针对具体业务目标的标注训练。", "supp": ["notes"], "term": "自监督学习 (Self-supervised Learning)", "usage": "它极大地降低了对昂贵人工标注数据的依赖，是大模型预训练的主流方法；PM 可据此理解大模型为何能在无标注的海量文本上完成基础训练。"}, {"cat": "技术术语", "concept": "双盲测试类比测试新药药效：给两组测评者分别提供 AI 生成内容和真人制作内容，但提供内容的人和测评者自己都不知道哪份是哪份，最后看测评者能否分辨出 AI 内容。它是一种更客观、严格的 AI 产品测试方法，目的是评估 AI 产出的质量是否足够以假乱真，能混入真实业务流程而不被下游的人察觉。", "id": "KB-012", "kp": 9, "kw": ["双盲测试", "以假乱真", "客观测评", "AI产出质量"], "notes": "使用这类测试时要注意，其结论来自测评者在不知情条件下的实际反应，比听专家吹嘘可靠得多，设计测试时要保持提供方与测评方都不知情这一前提。", "supp": ["notes"], "term": "双盲测试 (Double-blind Test)", "usage": "原文示例是测试 AI 写的销售邮件：让 AI 和资深销售各写 10 封邮件，随机打乱后发给目标客户经理（他们不知道有测试），统计客户经理对邮件的点击意向和好评率；如果 AI 组和人工组没显著差别，说明 AI 过关了。"}, {"cat": "技术术语", "concept": "Token 是大模型处理文本的最小单位，也是计费单位，可看作 AI 世界里的小额纸币或墨水：输入一句话或模型输出一段文字，都会按量换算并消耗若干 Token，一般一个字或一个词的片段大约就是一个 Token。英文里一个词大约 1-1.5 个 Token，中文更贵，一个汉字大约 1.5-2 个 Token。API 按输入 Token 和输出 Token 分别计费，输出通常比输入贵 2-4 倍。", "id": "KB-013", "kp": 0, "kw": ["Token", "计费单位", "输入输出", "成本测算", "上下文窗口"], "notes": "真正杀死 AI 项目的往往是成本，而成本的最小计量单位就是 Token；问题越复杂、回答越长，消耗越多、费用越高。不算这笔账的 AI 项目十个死九个，上线后账单可能直接干到六位数。", "supp": [], "term": "Token 词元", "usage": "PM 必须理解 Token 因为它关联两个产品决策：一是成本，如 System Prompt 有 2000 字约消耗 3000-4000 Token、每次调用都要发一遍，日均 10 万次调用光 System Prompt 一个月就烧几千到上万块；二是上下文窗口，模型能处理的 Token 总数有上限，减去 System Prompt、工具定义、对话历史后留给业务内容的空间有限。需求评审时让算法同事估算公式：单次 Token 消耗 × 日均调用量 × 单价 = 月成本，并写进 PRD。"}, {"cat": "技术术语", "concept": "上下文窗口可理解为 AI 的短期工作记忆容量，限制了一次沟通中 AI 能看到和记住的历史对话或文本有多长，单位是 Token，超过窗口的内容最早的部分会被遗忘。大模型本身没有记忆，每次 API 调用都是从零开始；产品里看到的多轮对话效果，是后端每次把 System Prompt 加上所有历史对话消息打包一起发给模型的结果，模型自己不存任何状态。", "id": "KB-014", "kp": 6, "kw": ["上下文窗口", "Context Window", "多轮对话", "滑动窗口", "摘要压缩"], "notes": "每多聊一轮发送内容就多一轮，Token 消耗线性增长直到撞到窗口天花板，满了最早的对话会被丢掉，用户会觉得 AI 忘事、答非所问。这块设计直接决定用户觉得 AI 聪明还是健忘，做不好用户留存会很难看。", "supp": [], "term": "Context Window 上下文窗口", "usage": "三种上下文保留策略：滑动窗口，只保留最近 N 轮对话，简单直接但会忘掉早期重要信息；摘要压缩，让模型把早期对话总结成摘要放在前面，省 Token 但会丢失细节；关键信息提取，把对话中的关键实体和决策单独提取存储，占 Token 最少但实现复杂。实际项目通常混合使用，如最近 3-5 轮完整保留、更早对话做摘要压缩、关键信息单独提取到 System Prompt 里。"}, {"cat": "技术术语", "concept": "这是对 Token 概念的进一步拆分。输入 Token 指你提问、发送文件等所有发送给模型的内容所消耗的量；输出 Token 指模型回答你、生成内容所消耗的量。例如你问帮我写一首关于春天的五言绝句，这句话本身是输入 Token，模型生成的诗句是输出 Token。", "id": "KB-015", "kp": 15, "kw": ["输入Token", "输出Token", "分开计费", "Token"], "notes": "通常输出更贵，因为生成内容比理解内容对模型的算力消耗更大，估算成本时不能只按输入量或总量粗算。", "supp": [], "term": "输入/输出 Token (Input/Output Token)", "usage": "在调用大模型时两者分开计费，PM 做成本核算时要把输入与输出两部分分别估算，再合计一次交互的总成本。"}, {"cat": "技术术语", "concept": "内容相似度是根据内容（如电影、文章）的标签（导演、主演、类型、关键词等）计算它们在数学向量空间中的距离，距离越近越相似。可以理解为算法在给每部电影贴完标签后，就能迅速找出和刚看完的电影长相最接近的其他电影。", "id": "KB-016", "kp": null, "kw": ["内容相似度", "向量空间", "标签", "距离"], "notes": "使用这类方法时要注意，它的相似判断完全建立在内容的标签之上，标签是否完整准确会直接决定算出的相似程度是否可信。", "supp": ["notes"], "term": "内容相似度", "usage": "可用于推荐：基于内容标签计算相似度，把与用户刚看完内容最接近的其他内容推荐给用户。"}, {"cat": "技术术语", "concept": "用户画像是通过用户的注册信息（年龄、性别、地域等）和行为数据（观看、点赞、搜索、购买等），为每一位用户生成一份数字化的特征档案，就像为用户绘制一张兴趣地图，记录了其静态属性和动态偏好。", "id": "KB-017", "kp": null, "kw": ["用户画像", "特征档案", "行为数据", "个性化推荐"], "notes": "使用用户画像时要注意，它由注册信息与行为数据构成，既包含静态属性也包含动态偏好，使用时应分清这两类信息的来源与性质。", "supp": ["notes"], "term": "用户画像", "usage": "用户画像是进行个性化推荐的基础，PM 可基于这份特征档案理解用户并支撑个性化推荐等产品设计。"}, {"cat": "技术术语", "concept": "协同过滤是一种物以类聚、人以群分的推荐思想，分两种主要方式：基于用户的协同过滤，找到和你兴趣爱好相似的用户群（邻居），把他们喜欢而你没看过的内容推荐给你；基于物品的协同过滤，分析物品之间的关联性，如果你喜欢电影 A，就把和 A 经常被同一批用户喜欢的电影 B 推荐给你，电商平台里的买了又买就是这个原理。", "id": "KB-018", "kp": null, "kw": ["协同过滤", "基于用户", "基于物品", "推荐"], "notes": "使用协同过滤时要注意，它依赖用户与物品之间已有的共同喜好与关联记录来做推断，推荐依据是群体行为上的相似与共现，而非内容本身的属性。", "supp": ["notes"], "term": "协同过滤", "usage": "PM 设计推荐时可按两种路径选用：按相似用户群推荐，如把相似用户新看的高分影片推荐给目标用户；或按物品关联推荐，如在电商场景做买了又买式推荐。"}, {"cat": "技术术语", "concept": "隐语义模型是一种更高级的推荐算法，它不直接依赖于用户或物品的显式标签，而是通过机器学习，从海量用户行为数据中自动挖掘出用户和物品背后隐含的兴趣主题或品类标签，然后基于这些隐性的联系来进行偏好预测。就像算法通过观察大量用户的观影记录，自己总结出一套看不见的分类标准，再用这套标准来推荐。", "id": "KB-019", "kp": null, "kw": ["隐语义模型", "隐含主题", "偏好预测", "推荐算法"], "notes": "使用这类模型时要注意，它所依据的分类标准是算法自行总结的隐性标准，并非人工定义的显式标签，理解推荐结果时不能按显式标签的逻辑去解释。", "supp": ["notes"], "term": "隐语义模型", "usage": "可用于偏好预测与推荐：先由算法从行为数据中挖掘隐含的兴趣主题，再基于这些隐性联系判断用户可能偏好的内容。"}, {"cat": "技术术语", "concept": "向量化是为了让计算机能理解并计算文本、图片等信息之间的相似性，把它们转换成一串有意义的数字即向量。就像用一组坐标来精确描述一个点的位置和方向，方便计算机进行距离和相似度计算。", "id": "KB-020", "kp": 19, "kw": ["向量化", "向量", "相似度计算", "距离"], "notes": "使用向量化时要注意，转换的目的在于让计算机可计算相似性，向量本身是一串有意义的数字表达，而非内容原文的直接呈现。", "supp": ["notes"], "term": "向量化", "usage": "PM 在涉及文本、图片相似性计算的产品设计中会用到向量化：先把内容转成向量，再由计算机做距离和相似度计算。"}, {"cat": "技术术语", "concept": "冷启动指一个新产品或新用户刚上线时，由于缺乏足够的历史行为数据，推荐系统难以做出精准推荐的问题。", "id": "KB-021", "kp": null, "kw": ["冷启动", "新用户", "历史数据不足", "兴趣标签"], "notes": "应对冷启动时要注意，上述方式是在历史行为数据不足时的过渡办法，其出发点与依赖充足行为数据的精准推荐不同，不能期待同样的精准程度。", "supp": ["notes"], "term": "冷启动", "usage": "常见解决方式包括：让新用户手动选择兴趣标签、利用物品的内容属性进行推荐、或者采用一些简单的流行度推荐策略。"}, {"cat": "技术术语", "concept": "在推荐系统中，马太效应指热门内容因为被点击得多，算法会倾向于更频繁地推荐它们，导致它们变得更热门；而冷门内容则曝光机会更少，变得更冷门。", "id": "KB-022", "kp": null, "kw": ["马太效应", "推荐系统", "信息茧房", "多样性下降"], "notes": "如果不加以控制，这会导致推荐结果的多样性下降，形成信息茧房；这是原文明确指出的风险，产品上需关注多样性是否被持续侵蚀。", "supp": [], "term": "马太效应", "usage": "PM 在设计和观察推荐系统时可用它来识别热门与冷门内容曝光被不断放大的现象，并据此考虑是否需要加以控制。"}, {"cat": "技术术语", "concept": "AB 测试是一种科学的对比实验方法：将用户流量随机分成 A、B 两组（或多组），让 A 组用户体验原有版本（对照组），B 组用户体验新版本（实验组，如新算法、新界面），通过对比两组用户的核心指标来判断新版本是否真的有效。", "id": "KB-023", "kp": 11, "kw": ["AB测试", "对照组", "实验组", "对比实验", "数据驱动"], "notes": "做 AB 测试时要注意，它的前提是流量随机分组与用核心指标做对比，判断依据应是两组数据的实际差异而非主观感觉。", "supp": ["notes"], "term": "AB测试", "usage": "PM 可用它驱动产品迭代：设定对照组与实验组，对比点击率、留存率等核心指标，用数据来判断新版本是否真的有效，再决定后续迭代方向。"}, {"cat": "技术术语", "concept": "人类反馈强化学习是给爱闯祸的 AI 学霸找个个人类导师：AI 写了一段话，导师（或用户）打分，写得好给奖励、胡说八道给惩罚。AI 通过不断接收这种人类偏好反馈来学习，目标是让自己的三观和行为更符合人类期待。这是 ChatGPT 等大模型变听话的核心技术之一。", "id": "KB-024", "kp": null, "kw": ["RLHF", "人类反馈", "强化学习", "偏好对齐"], "notes": "理解这一技术时要注意，它调整的是模型行为与人类偏好的符合程度，依据是人类给出的偏好反馈，而不是模型自行判断对错。", "supp": ["notes"], "term": "人类反馈强化学习（RLHF）", "usage": "PM 可将其理解为让大模型对齐人类偏好的核心手段：通过人类对输出的评分反馈，持续引导模型调整行为。"}, {"cat": "技术术语", "concept": "Prompt 是你和大模型沟通的指令或咒语。大模型本身知识包罗万象但目标不明确，需要通过清晰、具体的提示词来激活并引导它，告诉它你是谁、要做什么、用什么风格等，提示词的质量直接决定回答的质量。底层原因是大模型靠概率预测下一个 Token，Prompt 里的每一个词都在影响后续 Token 的概率分布；指令含糊，模型在多个方向上概率都差不多，输出就飘了。好 Prompt 四要素：角色设定、任务描述、输出约束、上下文信息。", "id": "KB-025", "kp": 1, "kw": ["Prompt", "提示词", "四要素", "思维链", "COT", "CRISPE"], "notes": "同一模型 Prompt 写得好和写得差，输出质量能差十倍；经手的 AI 项目里至少一半的效果问题最后都是优化 Prompt 解决的，不是换模型、不是加数据。Prompt 是 AI PM 性价比最高的技能，零成本、立刻见效；反之指令写得太糊，换模型也救不回来。没有 COT 时模型输出像黑盒子，很难理解它为什么得出某个结论，COT 让思考过程可被理解和检查。", "supp": [], "term": "Prompt  提示词", "usage": "写法上用四要素组织指令，缺一个输出就会发散；还可用思维链 COT：在提示里加入中间推理步骤的示例，引导模型一步步推理，包含分步提示设计、中间状态生成、结果提取三步，支持零样本和少样本两种模式；也可用提示词框架如 CRISPE，从角色与能力、洞察与背景、指令、风格、实验、响应格式等维度组织，确保不漏关键要素。原文示例对比：糟糕的提示词只说写首诗，优秀的提示词给定角色、背景、格式、内容和风格，效果天差地别。"}, {"cat": "技术术语", "concept": "Agent 是一个内置了大模型大脑，并配备了手脚（工具调用）和记事本（记忆）的 AI 程序。它能根据目标自主地分解任务、分步思考、调用工具，最终给出完整的成果。Agent 和聊天机器人的本质区别不是更聪明，而是它能动手干活：聊天机器人只能生成文字，Agent 能自己拆解复杂任务、规划步骤、调用外部工具执行操作、拿到结果后判断下一步。核心能力三件套是规划、工具调用、观察调整。", "id": "KB-026", "kp": 14, "kw": ["Agent", "智能体", "工具调用", "任务规划", "兜底策略"], "notes": "Agent 目前最大的问题是可靠性：每一步都有出错概率，多步串联后错误会累积。核心流程的设计时间和兜底策略的设计时间比例大概是 3 比 7，兜底比正常流程重要得多；任务流没有标准答案，每次执行路径可能都不一样。Agent 失败了用户可以接受，失败了还不告诉用户，用户绝对不能接受。", "supp": [], "term": "Agent  智能体", "usage": "产品设计范式随之改变：以前设计的是对话流，用户说什么 AI 回什么；现在设计的是任务流，用户说一个目标，Agent 自己规划怎么做。原文旅行规划智能体示例中，它先理解需求，再分步调用天气 API 查天气、地图 API 找景点、旅游资讯 API 搜路线、订票工具查酒店价格，最后综合信息生成包含行程、住宿建议和预算的完整攻略。"}, {"cat": "技术术语", "concept": "工作流是一套固定化、自动化的 AI 流水线：把一系列 AI 操作步骤像搭积木一样固定下来，按顺序执行。例如先从网上搜集资料，然后让一个大模型总结，再让另一个大模型润色，最后自动发布。它确保复杂任务能被稳定、可靠地重复执行。", "id": "KB-027", "kp": 14, "kw": ["工作流", "Workflow", "自动化流水线", "固定步骤"], "notes": "使用工作流时要注意，它的价值在于步骤被固定下来按顺序执行，适合需要稳定、可靠重复执行的复杂任务，步骤设计本身决定了整条流水线的产出。", "supp": ["notes"], "term": "工作流 (Workflow)", "usage": "原文内容创作运营工作流示例：第一步 RAG 从公司知识库检索新品信息；第二步模型根据信息生成初版宣传文案；第三步另一模型将文案改写成小红书风格并配上 emoji；第四步自动发布到预设账号。每次发新品只需启动这个工作流，内容就自动生成。"}, {"cat": "技术术语", "concept": "智能体平台是一个让你无需编程就能组装和发布智能体的工厂。平台提供图形化界面、现成的大模型接口、丰富的工具插件（如搜索、画图、读文档），你像搭积木一样把大脑、工具、记忆拖拽组合，定义好工作流程，就能创造出自己的 AI 助手，并发布给别人使用。", "id": "KB-028", "kp": 14, "kw": ["智能体平台", "Agent Platform", "低代码", "扣子", "Coze"], "notes": "使用智能体平台时要注意，它降低的是组装与发布的门槛，智能体的能力仍取决于所选的大脑引擎、所配工具与所定义的工作流程。", "supp": ["notes"], "term": "智能体平台 (Agent Platform)", "usage": "原文以字节跳动的扣子 Coze 平台为例：想做一个小红书爆款标题生成器智能体，可在平台里选择豆包作为大脑引擎，拖入联网搜索工具，再配置上传图片分析功能，然后告诉它智能体规则，配置好后得到专属的智能体链接分享给同事使用。"}, {"cat": "技术术语", "concept": "大模型引擎是提供大模型最核心的思考和生成能力的服务或产品，可理解为 AI 的心脏或发动机。智能体平台本身是个空壳，需要接入具体的引擎才能活起来。不同的引擎（如豆包、通义千问、DeepSeek、GPT）能力和擅长领域略有不同。", "id": "KB-029", "kp": 18, "kw": ["大模型引擎", "LLM Engine", "智能体平台", "模型能力"], "notes": "选用引擎时要注意，不同引擎能力和擅长领域略有不同，不能把平台本身当作能力来源，真正提供思考与生成能力的是所接入的引擎。", "supp": ["notes"], "term": "大模型引擎 (LLM Engine)", "usage": "原文类比：智能手机的操作系统可以安装不同的应用商店（智能体平台），而应用商店里的每个 APP（智能体）运行都需要手机的处理器（大模型引擎）提供算力支持，可按需选择不同引擎来驱动应用。PM 选型时应结合各引擎的能力与擅长领域来匹配产品需求。"}, {"cat": "技术术语", "concept": "RAG 是给易产生幻觉的大模型配一个外置知识库、让它开卷考试的能力：大模型在回答问题前，先去指定的数据库（如公司文档、个人笔记）里翻找相关资料，然后结合找到的资料生成答案，能让回答更准确、更具针对性，并大大减少胡说八道。核心流程四步：文档切段做 Embedding 存入向量数据库；用户问题也转成 Embedding；在向量库中检索语义最相似的文档段；把检索到的段落拼进 Prompt 让模型生成回答。大模型的知识在训练完那一刻就冻住了，公司内部规范等它并不知道。", "id": "KB-030", "kp": 2, "kw": ["RAG", "检索增强生成", "知识库", "Embedding", "向量数据库", "开卷考试"], "notes": "RAG 效果不好，80% 的问题不在模型上、在检索上，搜出来的文档片段不对，模型拿着错误资料回答当然答不到点上；检索质量是 RAG 的生死线，花在文档切分、Embedding 模型选型、Reranking 精排上的时间远超调模型。输入垃圾必定输出垃圾，源数据含互相冲突的信息时再好的构建也不可能输出高质量结果。当知识库中没有答案时，RAG 系统会提供看似可信但并不正确的答案而不会承认不知道，用户会收到错误信息。", "supp": [], "term": "RAG 检索增强生成", "usage": "原文示例：把公司财务报销制度 PDF 处理成知识库，用户问差旅住宿费最高能报多少钱，系统先查找相关段落，再基于查到的事实生成准确回答。解决知识库内容缺失要做两件事：清洁数据，包括移除噪声和不相关信息、识别和纠正拼写语法错误、去重；更好的提示词设计，如指示模型如果你不确定答案就告诉我你不知道，鼓励模型承认局限。"}, {"cat": "技术术语", "concept": "向量数据库是 RAG 技术的核心仓库。普通数据库按关键词或表格查找，向量数据库则按意思相似度查找。它专门用来存储文本向量（一段文本被转化成的一串数学坐标）；当你提问时，先将问题也变成向量，然后在整个向量库里快速搜索与这个问题向量距离最近（意思最相似）的文本块，这就是检索过程。", "id": "KB-031", "kp": 19, "kw": ["向量数据库", "Vector Database", "文本向量", "相似度检索", "RAG"], "notes": "使用向量数据库时要注意，它查找的依据是意思相似度而非关键词是否命中，理解其检索结果时应按语义距离而非字面匹配来判断。", "supp": ["notes"], "term": "向量数据库 (Vector Database)", "usage": "原文以图书馆为例：把所有书的特征转换成特征码（向量）存进特殊数据库，有人想找关于勇气的小说时，系统不是搜索书名里是否有勇气二字，而是将勇气也转成特征码，从库里找出特征码最接近的那些书推荐给读者。PM 在 RAG 类产品中可用它支撑按语义相似度的检索。"}, {"cat": "技术术语", "concept": "嵌入模型是负责把人话（文本）翻译成 AI 语言（向量）的翻译器。它可以把任何长短的文本都转化为一个固定长度的、富含语义信息的数字串（向量）；同样意思的文本，转化出来的向量在空间中就会靠得很近。它是连接人类知识库和向量数据库的桥梁。", "id": "KB-032", "kp": 19, "kw": ["嵌入模型", "Embedding", "文本向量", "语义相似"], "notes": "使用嵌入模型时要注意，它判断接近与否的依据是语义而非字面写法，写法不同但意思相同的文本会被视作相近，这是其检索效果成立的前提。", "supp": ["notes"], "term": "嵌入模型 (Embedding Model)", "usage": "原文示例：嵌入模型遇到猫、kitty、喵星人这三个词时，虽然写法不同，但会生成三个在高维空间里位置非常接近的向量，因为语义相似；而汽车生成的向量就会远得多。这样数据库才知道帮我找猫的照片和给我喵星人的图其实是一回事。PM 在知识库与检索类产品中要把它作为文本入向量库的必经环节。"}, {"cat": "技术术语", "concept": "Function Calling 是让大模型从空谈家变成实干家的关键能力。当大模型识别出意图需要执行某个具体操作时（如查天气、发邮件、记日程），它能生成一个结构化的命令，触发并调用外部程序、API 接口或数据库来完成真实世界的任务。模型自己不执行任何操作，它只做两件事：判断该调哪个函数、生成调用参数的 JSON；真正执行操作的是后端代码。运作流程是提前告诉模型有哪些工具函数可用及每个需要什么参数，用户发请求后模型选最合适的并输出结构化调用请求，后端执行后把结果返回给模型，模型再基于结果生成最终回复。", "id": "KB-033", "kp": 14, "kw": ["Function Calling", "函数调用", "工具调用", "结构化命令", "API"], "notes": "工具描述的质量直接决定模型选对工具的概率，描述写得模糊模型就会选错，如该查天气的去查日历、该下单的去查库存。把工具描述当 API 文档写，名称、功能、参数、返回值、使用场景都要写清楚。", "supp": [], "term": "Function Calling 函数调用", "usage": "PM 的核心工作不是写代码，而是定义四件事：工具集，你的 Agent 能用哪些工具、每个工具的功能描述要写到模型能理解的程度；使用条件，什么情况调什么工具、边界要清晰；优先级，多个工具都能用时先用哪个；错误处理，工具调用失败、超时、返回空结果时怎么办。原文订票示例中，智能体会生成带出发、到达、日期、时间、座位偏好的结构化指令传递给订票系统执行，而不是仅仅回复说会订票。"}, {"cat": "技术术语", "concept": "模型上下文协议 MCP 是由 Anthropic 公司推出的一个开源标准，旨在为不同的大模型和各种数据源、工具服务之间提供一个统一的插座标准。它规定了数据、工具应该以何种格式暴露给大模型，大大简化了开发者为大模型连接外部资源（如数据库、股票 API、项目管理软件）的复杂度。", "id": "KB-034", "kp": 14, "kw": ["MCP", "模型上下文协议", "Anthropic", "统一标准", "工具接入"], "notes": "理解 MCP 时要注意，它统一的是数据与工具暴露给大模型的格式标准，解决的是连接复杂度问题，本身并不提供某个具体工具的功能。", "supp": ["notes"], "term": "模型上下文协议 (MCP)", "usage": "原文示例：以前每个大模型要连接 12306 查票，都需要单独为它开发一套适配插件，就像不同品牌的手机需要不同形状的充电接口；有了 MCP，12306 只要提供一个符合 MCP 标准的插座服务，所有支持这个标准的模型都能直接插上使用，像 USB 一样通用便捷。PM 可据此理解工具接入为何能被标准化复用。"}, {"cat": "技术术语", "concept": "本条讲的是 MCP 服务器：一个遵循 MCP 协议标准，将某个具体服务（如查询天气、读取 Notion 笔记、管理待办清单）封装起来的独立程序。MCP 全称 Model Context Protocol，核心思路是把模型怎么用工具这件事标准化，就像 USB 协议统一了外设接口。MCP 定义了统一的通信格式，模型发出工具调用请求，MCP Server 接收并执行，结果按标准格式返回。三个核心角色：MCP Host 是大模型所在的应用，MCP Client 负责协议通信的中间层，MCP Server 是具体工具的服务端封装。只要工具包装成 MCP Server，任何支持 MCP 的模型和应用都能直接调用，不用单独写对接代码。", "id": "KB-035", "kp": 14, "kw": ["MCP", "MCP Server", "模型上下文协议", "工具封装", "权限管理"], "notes": "PM 需要重点关注工具注册和权限管理：产品能连哪些工具、用户有没有权限调用某个工具、调用失败怎么兜底，这些在产品层面必须设计清楚，不能全扔给开发，因为这些直接影响用户体验和安全性。工具对接效率不解决，Agent 产品的迭代速度就上不去。", "supp": [], "term": "MCP 模型上下文协议", "usage": "开发者可以编写或下载现成的 MCP 服务器，然后像安装 App 一样将它轻松集成到支持 MCP 的 AI 应用（如 Cherry Studio）中，立即扩展应用的能力。原文示例：编写一个豆瓣书单 MCP 服务器并在 Cherry Studio 中安装后，就能直接问 AI 助手根据豆瓣想读清单推荐一本书，助手会自动通过该服务器查询书单并回答。这样可避免每接一个工具都写一套对接代码、换模型供应商又重写一遍。"}, {"cat": "技术术语", "concept": "基础模型指一个已经完成了预训练（通识教育）的、未经后续特定调校的原始大模型。它知识渊博但性格或特长尚未定型，可以被视为一块璞玉或原材料，是进行各种下游微调、强化学习等操作的起点。常说的 DeepSeek、通义千问、LLaMA 等，都可以作为基础模型。", "id": "KB-036", "kp": 18, "kw": ["基础模型", "Base Model", "预训练", "微调起点"], "notes": "使用基础模型时要注意，它只是未经特定调校的起点与原材料，不能把其通用能力直接当作某个下游场景下已经定型的特长。", "supp": ["notes"], "term": "基础模型 (Base Model)", "usage": "原文示例：DeepSeek 最新版作为基础模型已具备强大的语言理解和生成能力，教育公司可以把它作为原材料，用儿童故事和教学对话数据微调成儿童故事大王；法律科技公司则可以用法律条文数据微调它，把它变成法律咨询助手，它们的起点都是同一个基础模型。"}, {"cat": "技术术语", "concept": "私有化部署是将大模型或基于大模型的应用，部署在自己的服务器、私有云或公司内部机房，而不是使用开箱即用的公有云服务（如直接网页使用 ChatGPT）。这样做主要是为了数据安全和隐私保护（数据不出内网），同时也可以根据自身业务需求进行深度定制和优化。", "id": "KB-037", "kp": 22, "kw": ["私有化部署", "数据安全", "隐私保护", "内网", "合规"], "notes": "采用私有化部署时其约束与收益都来自隔离本身：所有数据都留在机构内，确保了绝对的安全与合规；相应地，需要自行采购硬件与模型授权并在自有数据中心完成部署。", "supp": [], "term": "私有化部署 (Private Deployment)", "usage": "原文示例：一家大型医院希望用大模型辅助分析病历和提供诊断参考，由于病历数据高度敏感绝不能上传到公共云端，因此医院采购硬件服务器和某大模型的授权，在自己的数据中心部署了一套完全隔离的院内 AI 诊断系统。涉及高度敏感数据的场景可按此思路选择部署方式。"}, {"cat": "技术术语", "concept": "Skills 概念最初由 Anthropic（推出 Claude 的公司）提出，并很快发展为开放标准，OpenAI、微软、腾讯等大厂都迅速跟进支持，成为行业共识。通俗理解：现在的 AI 就像清华毕业的学霸，知识渊博，但让他去公司财务部门报销发票他可能会懵，因为不知道具体流程。Skills 就是一本本武功秘籍或岗位操作手册，当 AI 装上对应 Skill 后，就从什么都懂一点的学霸变成在这个岗位上干了 5 年的老员工，知道每一步该怎么走。", "id": "KB-038", "kp": 14, "kw": ["Skills", "技能", "Anthropic", "岗位操作手册", "开放标准"], "notes": "使用 Skills 时要注意，通用模型本身并不知道某个公司的具体流程、限额与审批要求，这些岗位知识需要靠装载对应的 Skill 来补齐，不能指望模型凭通用知识自行掌握。", "supp": ["notes"], "term": "Skills", "usage": "原文以公司财务小助手为例：没有 Skills 时，AI 面对处理报销单只能反问报销限额、审批人、发票格式要求；装了财务报销 Skill 后，AI 能扫描 PDF、识别 3 张发票并分别处理——餐饮发票符合标准已录入、交通发票缺少出差申请单附件已标记、住宿发票超标需副总特批已邮件通知，并生成 Excel 汇总表发送给财务总监。PM 可按具体岗位流程为 AI 配置对应的 Skill。"}, {"cat": "技术术语", "concept": "Agent to agent 通常称为多智能体协作，指的是多个具备自主感知、决策和执行能力的 AI 智能体，通过通信、协调与协商，共同完成一个复杂任务或实现共享目标的一种系统范式。可以想象成一个由多个专业数字员工组成的虚拟团队，每个智能体各有所长，它们之间可以对话、分配工作、共享信息、互相帮助，最终高效地完成一个人或单个智能体难以处理的大项目。", "id": "KB-039", "kp": 14, "kw": ["多智能体协作", "Agent to Agent", "数字员工", "通信协调"], "notes": "其协同逻辑是三个 Agent 通过共享的候选人 ID 数据库串联，前一个 Agent 完成任务后自动触发下一个；若背景调查发现问题，回推至面试官 Agent 重新评估。设计协作时需把这种异常回推路径一并考虑，而不是只设计顺利向前的流程。", "supp": [], "term": "Agent to agent（智能体间协作）", "usage": "原文以企业招聘流程自动化为例：简历筛选 Agent 从招聘网站抓取简历、初步筛选技能匹配度不低于 80% 的候选人；面试官 Agent 接收筛选结果，自动发送面试邀请邮件，并根据候选人时间偏好安排 Zoom 会议；背景调查 Agent 在面试通过后自动联系第三方 API 验证学历和工作经历。PM 可按专业分工拆分智能体并设计其串联方式。"}, {"cat": "技术术语", "concept": "流式输出是指模型每生成一个词就立刻推给用户，而不是等全部生成完再一次性展示。技术上通过 SSE 协议实现，后端和模型之间建立一个持久连接，模型每预测出一个 Token 就实时推送到前端，不等全部生成完。GPT-4 生成一段 500 字回答需要 10-15 秒，一次性展示时用户只会看到转圈动画；流式输出让文字一个个蹦出来，感知等待时间从 15 秒降到不到 1 秒。", "id": "KB-040", "kp": 13, "kw": ["流式输出", "Streaming", "SSE", "TTFT", "TPS"], "notes": "超过 3 秒用户开始烦躁，超过 8 秒直接关页面；原文产品上线后用户盯着空白页面等了 12 秒才看到回答，首日留存只有 15%，用户反馈最多的一条是太慢了。断流重连不提前设计，上线后必出问题。", "supp": [], "term": "Streaming 流式输出", "usage": "PM 需要盯三个指标并直接写进需求文档：TTFT，首 Token 延迟，用户发请求到看见第一个字的时间，这是用户感知快慢的关键；TPS，每秒输出 Token 数，决定文字蹦出来的速度；断流重连，网络波动时连接断了怎么续上。对生成类 AI 产品，流式输出不是锦上添花的体验优化，而是基本生存线。"}, {"cat": "应用工具", "concept": "Cherry Studio 是一款功能强大的 AI 工作台桌面软件。它支持同时连接多个不同的大模型服务（如豆包、GPT、本地部署的模型），并集成了 RAG 管理、MCP 服务器集市、工作流设计等核心功能。用户可以在一个界面里管理知识库、连接各种工具、设计复杂的 AI 应用逻辑，是 AI 应用开发者和重度用户的瑞士军刀。", "id": "KB-041", "kp": null, "kw": ["Cherry Studio", "AI工作台", "多模型", "RAG管理", "MCP集市"], "notes": "使用这类工作台工具时要注意，它集成的多模型连接、知识库管理与工作流设计需要在同一界面内统一配置，配置本身的质量决定最终助手的表现。", "supp": ["notes"], "term": "Cherry Studio", "usage": "原文示例：想基于公司产品文档打造智能客服，可在 Cherry Studio 里创建知识库并上传所有产品文档；连接豆包和通义千问两个模型让它们同时工作以互相验证答案；从社区集市安装一个查询订单状态的 MCP 服务器；设计工作流：用户提问先用 RAG 从知识库找答案、模型 A 生成回复、模型 B 审核回复的准确性和语气，配置好后得到一个私有客服助手原型。"}, {"cat": "应用工具", "concept": "魔搭社区是由阿里巴巴达摩院推出的、国内最大的 AI 模型开源社区和平台。它就像 AI 领域的 GitHub 加应用商店，用户可以在上面免费下载、体验、部署（包括私有化部署）国内外各种开源大模型、小模型、嵌入模型等，同时也提供大量可复用的 MCP 服务器、数据集和开发工具，是国内开发者和研究者重要的资源宝库。", "id": "KB-042", "kp": null, "kw": ["魔搭社区", "ModelScope", "开源模型", "阿里巴巴达摩院", "MCP服务器"], "notes": "使用该平台时要注意，它提供的是可下载、可复用的模型、数据集与工具资源，下载的现成代码通常仍需稍作修改才能集成到自己的应用中，不能默认拿来即可直接使用。", "supp": ["notes"], "term": "魔搭社区 (ModelScope)", "usage": "原文示例：学生想学习大模型但不想付费，可以上魔搭社区免费下载一个较小的开源模型并找到详细的本地部署教程；开发者想为项目添加天气查询功能，可以直接在魔搭社区搜索并下载一个现成的天气 MCP 服务器代码，稍作修改就能集成到自己的应用中。"}, {"cat": "应用工具", "concept": "ComfyUI 是一个主要用于文生图、图生图等 AIGC 领域的可视化编程工具。它将 Stable Diffusion 等复杂图像生成模型的每个步骤（如提示词解析、反推、图像加噪、去噪、放大）都拆解成一个个可以拖拽、连接、配置的节点，让用户可以精细、灵活地控制整个图像生成管线，极大地满足专业玩家和研究者的定制化需求。", "id": "KB-043", "kp": null, "kw": ["ComfyUI", "文生图", "可视化编程", "节点", "Stable Diffusion"], "notes": "使用该工具时要注意，它的优势来自把生成管线的每个步骤都拆成可配置节点，灵活度高的同时也意味着使用者需要理解每个节点在管线中的位置与作用。", "supp": ["notes"], "term": "ComfyUI", "usage": "原文示例：想画一个赛博朋克风格的猫，在 ComfyUI 里可以拖一个文本编码器节点输入提示词，再拖一个模型加载器节点选择喜欢的画风模型，然后连接采样器节点控制生成步数，最后连接图像放大器节点提升分辨率。通过可视化连接能清晰看到图片从无到有的生产线，并可随时替换其中任何一个零件来调整效果。"}, {"cat": "应用工具", "concept": "硅基流动是一个提供一站式大型模型服务与开发体验的云平台。它集成了模型服务、在线开发、Fine-tuning、RAG、智能体开发等多个模块。用户可以在上面直接调用各种前沿的模型 API，无需自己处理复杂的部署和运维；也可以使用平台提供的 Jupyter Notebook 环境和算力，进行模型微调、评估等实验，是快速验证 AI 想法的云端实验室。", "id": "KB-044", "kp": null, "kw": ["硅基流动", "Silicon Flow", "模型API", "云平台", "微调实验"], "notes": "使用该平台时要注意，它的定位是免去自建部署与运维、用云端环境快速验证想法，验证与实验都在平台提供的环境和算力上完成，与自建硬件路线的取舍需分清。", "supp": ["notes"], "term": "硅基流动 (Silicon Flow)", "usage": "原文示例：创业团队想验证用 AI 分析电商评论情感这个点子，可以在硅基流动平台上直接调用平台提供的多种情感分析模型 API，快速测试哪个效果最好；如果效果不佳，可用平台上准备好的电商评论数据集在线对选中模型进行微调实验；实验成功后可将微调好的模型一键部署为可调用的 API，快速集成到自己的产品原型中，整个过程都在云端完成，无需购买和配置任何硬件。"}, {"cat": "应用工具", "concept": "Nano CV 是一款主打对话式的 AI 简历优化工具，可想象成一个超级耐心的职业规划顾问，它会一步步问你问题（比如教育背景、工作经历、求职目标），然后帮你生成或优化简历。它专注于帮你做职业规划和求职准备，功能包括简历生成、优化、模拟面试等。通常是一个独立的网站或小程序，界面通常是简洁的聊天窗口，进入后它会主动打招呼并开始提问，问题一个接一个引导你完成信息输入，生成简历后界面提供编辑、下载等选项。", "id": "KB-045", "kp": null, "kw": ["Nano CV", "对话式", "简历优化", "模拟面试", "会员订阅"], "notes": "它采用会员订阅制：有免费体验版，功能受限，比如只能生成 1 份简历；付费会员解锁全部模板、无限次对话、高级功能等，费用从月度到终身会员不等，价格可能在几十到几百元。使用前需分清免费与付费的功能边界。", "supp": [], "term": "Nano CV", "usage": "使用者通过对话方式逐题回答它提出的问题来完成信息输入，随后由它生成或优化简历，并可在生成后进行编辑、下载；还可使用其模拟面试等求职准备功能。"}, {"cat": "应用工具", "concept": "这是百度文库 App 或网站内部集成的众多 AI 办公功能之一，在 AI 能力或 AI 求职里能找到。它更像一个表单填写机，目标是快速帮你出一份简历初稿。界面是非常传统的网页表单样式：第一步通常是让你从二三十种不同风格的简历模板里选一个，然后按步骤点选求职岗位、工作年限等，它会把你的选择自动变成文字塞进输入框，这种设计是为了减少不确定性，让操作更简单。访问需在百度文库 App 或网页版找到入口并登录百度账号。", "id": "KB-046", "kp": null, "kw": ["百度文库", "AI生成简历", "表单", "模型幻觉", "VIP会员"], "notes": "根据反馈，这个工具有时会胡说八道（专业术语叫模型幻觉），比如编造你没有的工作经历、证书，甚至联系方式，使用时需要仔细核对。另外，如果想下载生成好的简历文件（PDF/Word），通常需要开通百度文库的 VIP 会员，这也是它推广会员服务的一种方式。", "supp": [], "term": "百度文库AI生成简历", "usage": "使用路径是进入百度文库的 AI 能力或 AI 求职入口，选择生成简历，先选模板，再按步骤点选岗位与年限等信息，由工具自动生成简历初稿文字；生成简历、查看简历是免费的。"}, {"cat": "应用工具", "concept": "扣子 Coze 不是一个现成的产品，而是一个 AI 产品制造工厂，由字节跳动推出，是一个低代码/零代码的 AI 应用开发平台。你可以像搭积木一样，用拖拉拽的方式把大语言模型、各种插件、工作流组合起来，自己创建一个 AI 应用，比如智能英语老师、自动生成短视频的机器人，也包括 AI 简历优化器。界面像一个高级版的流程图或积木编辑器，主界面是一个大画布，可在上面拖放开始节点、大模型节点、插件节点、结束节点等各种节点，然后用线把它们按逻辑连起来，形成一个自动化的工作流程。官网是 coze.cn，注册登录后就可以开始搭积木。", "id": "KB-047", "kp": null, "kw": ["扣子", "Coze", "字节跳动", "低代码", "智能体平台", "工作流"], "notes": "扣子本身对个人开发者有免费额度，它本身并不直接作为成品产品提供价值，价值来自用它开发出的应用；评估它时应区分平台本身与基于它做出的应用。", "supp": [], "term": "扣子 (Coze)", "usage": "开发者在画布上拖放并连线各类节点、组合模型与插件来搭建自己的 AI 应用；其商业价值在于能用它快速开发出能解决实际问题的 AI 应用，然后把这个应用作为服务卖给别人，或者集成到自己的业务里。"}, {"cat": "应用工具", "concept": "DeepSeek 不是一个直接可用的产品，而是驱动很多 AI 产品的发动机。它是国内研发的一款非常强大的大语言模型（可理解为 AI 的大脑），能力类似于 ChatGPT。像 Nano CV 这样的产品，其背后思考和生成文字的核心，很可能就使用了 DeepSeek 这类模型。它有官方网页版和 App，界面极其简洁，就是一个对话框，你输入问题，它给出回答；它的强大在于理解和生成文字的能力，而不是花哨的界面，通常是免费的。", "id": "KB-048", "kp": null, "kw": ["DeepSeek", "大语言模型", "聊天机器人", "国产模型"], "notes": "理解 DeepSeek 时要注意区分模型与产品：它本身是作为大脑的大语言模型，基于它做出的具体产品与直接使用它的聊天界面是两回事，不能混为一谈。", "supp": ["notes"], "term": "DeepSeek", "usage": "可以直接把它当作一个超级聪明的聊天机器人来用，让它帮你分析简历、优化措辞、预测面试问题；也可作为其他 AI 产品背后的核心模型来理解其能力来源。"}, {"cat": "应用工具", "concept": "ChatGPT 是由 OpenAI 开发的、目前全球影响力最大的大语言模型产品（通常指基于它的聊天交互应用）。它被公认为当前能力的标杆，是天花板级别的存在，许多技术标准和技术效果都是以它作为参照。", "id": "KB-049", "kp": null, "kw": ["ChatGPT", "OpenAI", "行业标杆", "大语言模型"], "notes": "其 API 使用成本也相对较高，是典型的高质高价选择；选型时需把这一成本特征与标杆级能力放在一起权衡。", "supp": [], "term": "ChatGPT", "usage": "学习产品开发时可把它作为行业标杆来参照：不仅要了解可落地的选择，也要知道行业标杆在哪里，以它为参照衡量技术标准与效果。"}, {"cat": "应用工具", "concept": "豆包是由字节跳动推出的国产大语言模型产品，通过 App、网页等提供对话服务。它是国内大厂激烈竞争中一个重要选手，常被用于比较评测中，其未来也可能成为 AI 应用可集成的模型来源之一。", "id": "KB-050", "kp": null, "kw": ["豆包", "字节跳动", "国产大语言模型", "对话服务"], "notes": "原文对豆包的介绍仅限于其出品方、提供形式与竞争定位，未给出更具体的能力或使用细节，引用时不应超出这一范围做更具体的断言。", "supp": ["usage", "notes"], "term": "豆包", "usage": "豆包可通过 App、网页等渠道使用其对话服务，也可在做模型比较评测时作为国产大语言模型的代表之一纳入对比。"}, {"cat": "应用工具", "concept": "这是一类比简单简历生成更高级的 AI 工具构想，它不止帮你写简历，更能像一个真正的职业教练一样工作。核心工作原理包括三步：深度匹配分析，你上传简历和目标岗位的招聘要求 JD，AI 像 HR 一样对比两者，找出优势和差距，甚至打个匹配分数；针对性优化，根据差距不仅润色文字，还教你如何用 STAR 法则重写经历或用具体数据量化成果；模拟面试训练，基于优化后的简历预测面试官可能问的问题，并进行文字甚至语音的模拟对话，训练应答技巧，包括如何应对压力面试。", "id": "KB-051", "kp": null, "kw": ["AI简历优化器", "AI面试教练", "JD匹配", "STAR法则", "模拟面试"], "notes": "理解这一概念时要注意，它目前是比简历生成更高级的工具构想，其价值建立在深度匹配、针对性优化与模拟训练三步完整成立的基础上，而非仅生成一份简历文本。", "supp": ["notes"], "term": "AI简历优化器 / AI面试教练（产品概念）", "usage": "对求职者来说，它能极大提升简历质量和面试准备水平；对企业或培训机构来说，是一款可以收费的高价值服务产品。使用者按上传简历与 JD、接受针对性优化建议、再进行模拟面试训练的路径使用它。"}, {"cat": "应用工具", "concept": "智能简历匹配解决的痛点是简历和岗位描述不匹配：很多人只知道自己干了什么，却不会提炼成企业需要的关键词，导致简历在 HR 或初筛系统中就被过滤掉。本案例的功能是：上传旧简历和心仪职位的招聘描述 JD 后，AI 分析匹配度，指出哪些技能、经历符合、哪些缺失；提供改写建议；一键生成优化版简历，自动调整结构、用词。", "id": "KB-052", "kp": null, "kw": ["智能简历匹配", "JD", "匹配度", "语言对齐", "RAG", "Prompt"], "notes": "使用这类产品时要注意，其要解决的不是简历写得好不好看的问题，而是简历语言与岗位要求不对齐、被初筛过滤的问题，评估效果应看匹配与对齐是否改善，而非只看文本是否更华丽。", "supp": ["notes"], "term": "智能简历匹配（产品案例）", "usage": "原文改写建议示例：把负责项目管理改成独立主导 3 个超过 50 万元预算的跨部门项目，准时交付率达 98%。其产品价值的核心竞争力是精准解析岗位要求并实现语言对齐，帮求职者把我有能力翻译成这正是你要的人，是典型的利用 RAG 加 Prompt 技术解决高频率、高焦虑个人需求的产品，是一个从需求洞察到技术实现的完整产品 demo。"}, {"id": "KB-053", "term": "周报智能体 / 职场外挂（产品概念）", "cat": "应用工具", "concept": "设想中的AI工作秘书类智能体，解决每周写周报耗时痛苦、需回忆琐事并包装成对齐公司目标和KPI的成果这一痛点。它能整合碎片记录，提炼结构化成果，再按团队偏好格式生成周报初稿。", "usage": "自动汇聚邮件、聊天记录、代码提交、会议纪要和待办完成情况；基于岗位KPI和公司近期目标分析记录，提炼关键成果、挑战和下一步计划；生成有数据、有逻辑、有亮点的周报初稿，用户只需微调润色即可提交。", "notes": "原文未专门说明风险。需注意它属于产品概念而非已验证产品，落地前应先验证数据整合与生成质量是否真实可用。", "supp": ["notes"], "kw": ["周报", "智能体", "多源数据整合", "KPI对齐", "工作秘书"], "kp": 4}, {"id": "KB-054", "term": "AI媒体矩阵工具（产品构想）", "cat": "应用工具", "concept": "利用AI实现内容海量生产加多渠道分发的自动化流量获取构想，解决一个人无法靠人工运营几十甚至几百个小红书、抖音账号卖货引流的问题。核心环节包括热点抓取分析、内容批量生成、矩阵自动分发和流量汇聚变现。", "usage": "用AI爬虫监控各平台爆款内容、热门话题和数据变化；按热点要素和内容结构批量生成风格、文案、图片或视频各异的内容；自动管理大量账号分发到不同平台账号；所有内容导向同一商品链接或微信号等目标集中变现。适合MCN机构、网红、电商卖家低成本规模化获取流量。", "notes": "原文未专门说明风险。这是产品构想而非已落地产品，规模化分发前需先验证内容质量与账号运营的可行性。", "supp": ["notes"], "kw": ["媒体矩阵", "批量生成", "自动分发", "流量变现", "热点抓取"], "kp": null}, {"id": "KB-055", "term": "AI查重工具（产品构想）", "cat": "应用工具", "concept": "从企业招聘端提出的矛与盾式构想：求职者用AI优化简历后，招聘公司需要工具反制。它用专门算法分析简历的用词规律、句子结构等文字特征，判断简历有多大可能由AI生成而非求职者本人所写。", "usage": "帮助企业HR更高效、更公平地筛选海量简历，应对AI简历美化带来的挑战、提高招聘质量；还可做标准化面试辅助，为HR或面试官生成针对岗位和简历的结构化面试题，记录回答并给出AI评分。可作为面向企业的B端SaaS服务销售。", "notes": "原文未专门说明风险。检测结论只能作为筛选参考，不宜仅凭AI生成痕迹直接否定候选人，应结合面试等环节综合判断。", "supp": ["notes"], "kw": ["AI查重", "简历检测", "标准化面试", "B端SaaS", "招聘筛选"], "kp": null}, {"id": "KB-056", "term": "私域Agent（私域智能体）", "cat": "应用工具", "concept": "指能自动执行企业在私域流量中运营、营销、客服等任务的AI机器人，私域包括企业微信客户群、微信公众号粉丝群、品牌会员社群等。该条目原文说明其是用于测算市场规模的参考性产品概念。", "usage": "可7x24小时自动回答群内常见问题、根据用户行为自动推送商品或活动、在群内发起互动游戏、维护群秩序如踢广告、收集用户反馈。用AI替代或辅助人工完成私域运营中重复、规则性强的任务。", "notes": "原文未专门说明风险。自动化运营应聚焦重复、规则性强的任务，复杂或敏感的用户问题仍需人工把关。", "supp": ["notes"], "kw": ["私域流量", "企业微信", "自动客服", "社群运营", "智能体"], "kp": 14}, {"id": "KB-057", "term": "创客贴、来画、水母智能、Nui", "cat": "应用工具", "concept": "这是在AI图片设计、视频生成细分赛道上已经获得风险资本投资的真实存在的产品公司，并非单一工具条目。原文列举它们是为了论证AI生成内容这一产品方向已被市场验证和看好。", "usage": "PM思考自己产品方向时可把它们当前车之鉴：把AI能力聚焦到某个垂直应用领域，如设计海报、做短视频，可以做成有价值、可融资的独立商业产品。", "notes": "原文未专门说明风险。列举目的是论证方向而非要求记住每个名字，不应把融资案例直接等同于自身产品必然成功。", "supp": ["notes"], "kw": ["AIGC", "垂直应用", "设计工具", "视频生成", "市场验证"], "kp": null}, {"id": "KB-058", "term": "玄学Agent（产品概念）", "cat": "应用工具", "concept": "用于激发想象力和拓展产品边界的脑洞概念：基于八字、塔罗牌、星盘等东西方玄学理论体系，为用户提供运势解读、未来趋势建议或情感分析等服务的AI应用。", "usage": "讨论价值在于说明AI产品化可能性极广：不仅能解决严肃的工作问题，也可切入精神消费、情感陪伴、文化娱乐等需求。设计产品时要跳出工具框框，思考能否满足用户精神上的需要或文化上的认同。", "notes": "原文未专门说明风险。该条目是拓展思路的概念示例，不代表其结论或服务具有事实依据，产品化时需注意表述边界。", "supp": ["notes"], "kw": ["玄学", "情感陪伴", "精神消费", "产品概念", "文化娱乐"], "kp": null}, {"id": "KB-059", "term": "彩云小梦", "cat": "应用工具", "concept": "一款专门帮用户写故事的AI助手。用户只需提供故事开头、人物和背景设定，它就能自动续写下去，并常常提供好几个不同走向的情节版本供选择。", "usage": "适用于小说创作、剧本构思、头脑风暴、解决写作卡文的烦恼，以及给孩子编睡前故事等场景。", "notes": "原文未专门说明注意事项。使用时应提供清晰的开头、人物与背景设定，以便续写更贴合预期。", "supp": ["notes"], "kw": ["故事续写", "小说创作", "剧本构思", "头脑风暴"], "kp": null}, {"id": "KB-060", "term": "海螺AI (Hailuo AI, 出品方：Minimax)", "cat": "应用工具", "concept": "Minimax公司推出的一款强大的AI视频生成产品，用户可以用文字直接生成高质量的视频片段。原文还提到其近期将高级套餐价格大幅上调至每年过万元，在市场上引起很大争议和讨论。", "usage": "适用于短视频创作、广告制作、内容营销、创意演示、个人Vlog素材生成等场景。", "notes": "原文提及的高级套餐涨价争议提示：选用此类工具时需关注其定价变动对使用成本的影响。具体价格以官方信息为准，原文未给出套餐细节。", "supp": [], "kw": ["视频生成", "文生视频", "Minimax", "短视频创作", "内容营销"], "kp": null}, {"id": "KB-061", "term": "可灵AI (Kling AI)", "cat": "应用工具", "concept": "一款备受瞩目的AI视频生成工具，由快手公司推出。与海螺AI类似，主要用于文字生成视频，在生成视频质量和运动感方面表现出色。", "usage": "适用于文字生成视频场景，可用于短视频等内容创作，原文将其与海螺AI作同类对照。", "notes": "原文未专门说明注意事项。原文信息较简略，功能与使用细节需以产品官方说明为准，不要据此条目推断未写明的能力。", "supp": ["notes"], "kw": ["视频生成", "文生视频", "快手", "运动感"], "kp": null}, {"id": "KB-062", "term": "Floofy / 智能仙人掌 (Floofy Smart Cactus)", "cat": "应用工具", "concept": "一款外形设计成可爱仙人掌的实体智能玩具或教育产品，智能核心在于植入大模型能力，让孩子可以通过语音与仙人掌对话、互动和问答。是典型的为非智能传统产品增加AI功能的例子。", "usage": "适用于儿童陪伴、启蒙教育、智能玩具、家庭教育辅助等场景。这类功能升级型产品采用价值基础定价法，即根据用户感知到的价值定价，而不是简单按成本叠加。", "notes": "原文未专门说明风险。面向儿童的产品需格外注意内容与使用安全，原文未展开，具体要求应另行核查。", "supp": ["notes"], "kw": ["智能玩具", "语音对话", "儿童陪伴", "价值定价", "AI硬件"], "kp": null}, {"id": "KB-063", "term": "燕雀智能 (YanQue AI)", "cat": "应用工具", "concept": "一款专注于Logo设计的AI工具。用户输入品牌名称、行业和风格偏好，AI可以快速生成多个Logo设计方案。原文以其收费方式作为按次定价模式的典型代表。", "usage": "适用于初创公司、小微企业、个人品牌、自媒体快速生成品牌视觉标识。其收费模式非常直接，采用按创作次数收费，例如9.9元可以生成一次并获得若干方案。", "notes": "原文未专门说明注意事项。原文给出的9.9元为示例性价格说明，实际收费应以产品当期规则为准。", "supp": ["notes"], "kw": ["Logo设计", "按次定价", "品牌视觉", "快速生成"], "kp": null}, {"id": "KB-064", "term": "Minimax Agent", "cat": "应用工具", "concept": "Minimax公司推出的AI智能体开发平台，可理解为高级AI应用搭建工厂，面向开发者和企业客户，允许他们创建能够自主执行复杂任务的智能程序，如数据分析、客服、流程自动化。", "usage": "适用于企业级自动化流程开发、定制化AI助手、复杂业务智能体构建。作为典型B端和开发者产品，其定价较高，并采用点数即任务额度来量化和计量服务消耗，可为这类产品定价提供参考。", "notes": "原文未专门说明风险。企业级使用前需结合其较高定价与点数计量方式评估成本，原文未给出具体价格数字。", "supp": ["notes"], "kw": ["智能体平台", "Agent", "企业级", "流程自动化", "点数计费"], "kp": 14}, {"id": "KB-065", "term": "Cursor", "cat": "应用工具", "concept": "一款集成了顶尖AI能力的智能代码编辑器。它不只是代码高亮和补全，更能通过对话理解编程意图，直接生成或修改代码块，像一位坐在身边的资深程序员搭档。原文举例其集成了GPT-4等能力。", "usage": "适用于程序员和开发者进行高效编码、代码重构、调试、学习新语言或框架等场景。", "notes": "原文未专门说明注意事项。AI生成或修改的代码仍需开发者审查验证后再使用，不能直接默认其正确。", "supp": ["notes"], "kw": ["代码编辑器", "AI编程", "代码生成", "代码重构", "调试"], "kp": null}, {"id": "KB-066", "term": "产品", "cat": "产品名词", "concept": "只要能满足某种需求的东西都可以称为产品，包罗万象：手里的手机是有形物品，购买的在线课程是无形服务，认同的理念或加入的社群也属产品。其核心逻辑是一头是需求即有人需要，另一头是商业交换即有人提供并从中获益。", "usage": "理解产品时用需求加商业交换两端来判断：如买一瓶水，水满足口渴需求、付钱完成交换，水就是产品；微信、抖音等APP通过提供服务满足社交、娱乐需求，同样是产品。", "notes": "原文未专门说明注意事项。判断一件事物是否为产品，应回到是否满足需求并发生商业交换这一核心逻辑，不要只按有形物品理解。", "supp": ["notes"], "kw": ["产品", "需求", "商业交换", "服务"], "kp": null}, {"id": "KB-067", "term": "产品思维", "cat": "产品名词", "concept": "一种为他人着想、最终成就自己的思维方式：把解决别人的问题作为出发点，认为只有先让别人获益如用户满意，自身的价值如职场发展或商业目标如公司盈利才能实现。这是一种可以迁移到工作、学习和生活中的成长型思维。", "usage": "做内部系统时不只想完成任务，而要想同事操作时最大的痛点是不好用还是步骤繁琐、怎么设计让他们更省力更开心，解决了同事的问题项目自然成功。菜市场卖米的三哥为老客户提供积分和送货上门、最终把小店做成连锁品牌，也是产品思维的体现。", "notes": "原文未专门说明注意事项。运用产品思维要真正从用户痛点出发，而不是只停留在完成任务层面。", "supp": ["notes"], "kw": ["产品思维", "用户痛点", "利他", "成长型思维"], "kp": null}, {"id": "KB-068", "term": "PMF (产品与市场匹配)", "cat": "产品名词", "concept": "Product-Market Fit，指产品正好匹配了市场上一个用户群体强烈且未被满足的需求，简单说就是做的东西正好是别人想要的。这是产品能否成功最关键、最基础的一步，没达到PMF，再多的推广也像在沙地上建高楼。", "usage": "用未被满足的强需求来检验：早期打车软件爆发，是因为路边等车、和司机议价尤其恶劣天气下是巨大痛点，打车软件用手机叫车、在线支付、路线透明一一化解痛点，实现了PMF。因此有世界上只有两种公司、找到PMF的和没找到的说法。", "notes": "没有PMF时不要靠加大推广硬推，应先回到需求是否强烈且未被满足这一根本问题上验证。", "supp": [], "kw": ["PMF", "产品市场匹配", "未满足需求", "痛点"], "kp": 16}, {"id": "KB-069", "term": "商业模式", "cat": "产品名词", "concept": "通俗讲是一个公司怎么赚钱的完整逻辑设计图，要说清：为谁创造了什么独特价值、价值通过什么渠道送到客户手中、如何建立联系并留住他们、钱从哪里来、成本花在哪。把这些要素及关系画清楚，就构成商业模式的骨架。", "usage": "可用经典案例理解：剃须刀公司把刀架定得很便宜甚至免费、刀片很贵且需持续更换，是剃刀与刀片模式；超市靠巨大客流量从供应商拿到极低采购价并让利消费者、换取更大客流量形成良性循环，也是其商业模式。即钱转一圈、多出一点的设计。", "notes": "原文未专门说明注意事项。设计商业模式需把客户、价值、渠道、收入与成本等要素及其关系一并说清，不能只谈收入一端。", "supp": ["notes"], "kw": ["商业模式", "价值主张", "收入来源", "成本结构", "剃刀与刀片"], "kp": null}, {"id": "KB-070", "term": "漏斗模型", "cat": "产品名词", "concept": "帮你查看和分析用户从知道产品到最终付费全过程的工具。像口朝上的漏斗，顶部最宽代表最开始知道产品的人最多，每往下一层就有一部分用户因太贵、操作复杂等原因离开，越往下人越少，最终产生购买的用户最少。它帮你找出流失最多的环节对症优化。", "usage": "以电商大促为例分层计算转化率：曝光10万人、点击2万人、浏览详情1.2万人、加购6000人、下单3000人；点击到浏览转化率是60%。若加购到下单转化率特别低，可能需优化支付流程或提供运费优惠。PM按层定位流失环节再针对性改进。", "notes": "原文未专门说明注意事项。分析时要逐层算转化率、定位具体流失环节，不要只看最终成交总量下结论。", "supp": ["notes"], "kw": ["漏斗模型", "转化率", "用户流失", "曝光", "下单"], "kp": null}, {"id": "KB-071", "term": "MVP（最小可行产品）", "cat": "产品名词", "concept": "最小可行产品，指用最低成本、最快速度验证核心商业猜想的简化产品。原文以餐馆为例：与其花50万租店装修雇齐人手做完整菜单，不如先花5000块摆小摊只卖一款最核心的酸菜鱼看购买和反馈，这个小摊就是MVP，只做解决核心痛点的一个或少数关键功能。", "usage": "初创阶段资源有限、市场不确定，做功能完整体验完美的产品周期长风险大。MVP主张聚焦核心、快速试错：迅速推向市场收集真实反馈，用反馈指导下一步是加大投入还是赶紧调整方向，避免闭门造车、无效烧钱。", "notes": "注意MVP是验证工具而非粗糙成品借口：只保留核心关键功能，其余从简；受欢迎与否要以真实市场反馈为准，而非内部臆测。", "supp": [], "kw": ["MVP", "最小可行产品", "快速试错", "核心功能", "验证"], "kp": 16}, {"id": "KB-072", "term": "LTV（用户生命周期价值）", "cat": "产品名词", "concept": "用户生命周期价值，指一个用户从成为用户到最终流失为止，在产品上消费的总金额。如用户首次买99元会员、后来续费2年每年99元、期间又买3次单价50元增值服务，LTV约为99+99×2+50×3=447元。把用户比作果树，LTV就是其一生摘走的总消费。", "usage": "LTV帮你衡量一个用户到底值多少钱，是衡量产品商业健康度尤其订阅制产品的核心指标。它告诉你从长远看获取一个用户的投入是否值得，应与获取成本结合判断。", "notes": "原文未专门说明注意事项。LTV需按完整生命周期累计计算，不能只看首次消费金额来判断用户价值。", "supp": ["notes"], "kw": ["LTV", "生命周期价值", "订阅制", "用户价值"], "kp": 15}, {"id": "KB-073", "term": "CAC（用户获取成本）", "cat": "产品名词", "concept": "CAC是平均获取每个付费用户所花的代价，包括广告费、渠道佣金、销售提成等。如花1000元在社交媒体打广告带来20个付费用户，平均每人50元，这50元就是CAC，是引来一颗果树付出的代价。", "usage": "CAC与LTV是衡量商业模式健康与否的孪生兄弟，需成对使用：健康的商业模式基本要求是LTV大于3倍CAC，即用户生命周期价值是获取成本的3倍以上。", "notes": "如果CAC长期高于LTV，意味着每获得一个用户都在亏钱、不可持续。评估获客投入时必须把广告、佣金、提成等成本算全。", "supp": [], "kw": ["CAC", "获客成本", "LTV", "商业健康度"], "kp": 15}, {"id": "KB-074", "term": "领域概念", "cat": "产品名词", "concept": "本条目原文是对几类客户领域概念的并列说明：To B面向企业客户、To G面向政府部门、To A面向军队、To School面向学校。不同领域在流程、合规、预算与关注点上各有特点，并非单一术语的统一定义。", "usage": "区分时抓各领域特点：To B注重流程嵌入、数据安全、定制化需求和投资回报率；To G对合规性、安全性、预算执行、政策响应有特殊要求、流程相对复杂；To A文中提到预算充足、技术指标要求高、涉及敏感信息且回款流程稳定；To School当前预算可能相对紧张，更注重实用性、易用性和教育价值。", "notes": "原文未专门说明注意事项。各领域特点是原文的概括性描述，具体项目仍需按实际客户要求核实，不能一概而论。", "supp": ["notes"], "kw": ["To B", "To G", "To A", "To School", "领域"], "kp": null}, {"id": "KB-075", "term": "Kano模型", "cat": "产品名词", "concept": "帮你给用户需求分类、排优先级的经典模型，指出并非所有用户要求都同样重要。它将需求分为五类：必备属性是底线功能、没有会极度不满；期望属性越多越好、满意度线性变化；魅力属性是没想到惊喜功能、提供后满意度飙升；反向属性是用户讨厌的功能、提供反而降满意度；无差异属性是提供与否用户都无所谓。", "usage": "以外卖APP为例应用：必备是能点餐、能送餐、能在线支付；期望是送餐准时、商家多、餐品图清晰；魅力如雨天点餐自动赠送雨天关怀优惠券；反向如强制看5秒广告才能打开；无差异如主色调微调。用它确认需求是否存在、分清等级，把钱花在刀刃上，避免在用户无感功能上浪费资源，同时找到打造爆款的惊喜点。", "notes": "注意避开两类浪费：在无差异属性上投入资源用户无感，加入反向属性功能反而招致反感。必备属性缺失会引发极度不满，必须优先保障。", "supp": [], "kw": ["Kano模型", "必备属性", "期望属性", "魅力属性", "需求优先级"], "kp": 21}, {"id": "KB-076", "term": "需求挖掘五步法", "cat": "产品名词", "concept": "使用Kano模型科学挖掘和筛选需求的标准操作流程，把用户的感觉变成可衡量的数据。五步为：正反两面提出问题、使用量表收集评价、多人统计计算系数、比较优劣势、四象限分析定位。", "usage": "具体操作：针对功能点正反提问如有此功能感觉如何、没有又如何；让用户按喜欢、理应如此、无所谓、能忍受、不喜欢量表打分；收集足够样本计算Better系数即提供后满意度提升程度与Worse系数即不提供后满意度下降程度；据Better-Worse系数矩阵比较，再放入魅力、期望、必备、无差异四象限确定开发优先级。如美颜相机AI一键生成写真调研1000份反馈，Better高、Worse低，落入魅力象限值得打造。", "notes": "原文未专门说明注意事项。该方法依赖足够样本的问卷统计，样本不足时系数与象限定位不可靠。", "supp": ["notes"], "kw": ["需求挖掘", "Kano", "Better系数", "Worse系数", "四象限"], "kp": 21}, {"id": "KB-077", "term": "HMW模型", "cat": "产品名词", "concept": "HMW即How Might We，我们可以如何……，是一种激发创意、重新定义问题的解题思维方式。当遇到问题时，用我们可以如何……开头来重述问题，打开思路，寻找各种可能的解决方案。", "usage": "以用户总是忘记保存编辑文档为例多角度提问：积极角度问如何让保存更自动更无感；转移角度问如何让用户根本不需要手动编辑保存如语音输入自动成文；否定角度问如何让保存不再必要如实时云端同步；脑洞拆解角度问如何把保存变成有趣的游戏化体验。从而从优化保存流程的单一思路拓展到改变交互方式甚至重构产品形态。", "notes": "原文未专门说明注意事项。使用时应从多个角度发问，避免只沿单一思路如仅优化原流程寻找答案。", "supp": ["notes"], "kw": ["HMW", "How Might We", "问题重定义", "创意激发"], "kp": null}, {"id": "KB-078", "term": "五层结构模型", "cat": "产品名词", "concept": "把产品像剥洋葱一样从外到里、从抽象到具体拆解为五个层次的系统框架：战略层是初心与终点含产品目标、用户需求和商业模式；范围层是功能菜单含功能规格与内容需求；结构层是骨架含交互设计与信息架构；框架层是布局含界面、导航与信息设计；表现层是皮囊与气质即用户直接感知的视觉听觉等感官设计。", "usage": "以微信扫一扫为例逐层分析：战略是连接线下入口拓展支付社交场景；范围含扫码支付、加好友、识别二维码条形码；结构是入口在首页右上角加号菜单、点击进入全屏扫码界面；框架是界面中央扫描框、下方功能切换栏；表现是简约绿白色、图标清晰反馈及时。用五层分析竞品能看透每个设计背后的原因。", "notes": "原文未专门说明注意事项。拆解时应逐层完整分析，不要只停留在表现层等表面层次而忽略战略与范围等上层逻辑。", "supp": ["notes"], "kw": ["五层结构", "战略层", "范围层", "结构层", "框架层", "表现层"], "kp": null}, {"id": "KB-079", "term": "竞品分析六步骤", "cat": "产品名词", "concept": "一套有章法地研究竞争对手并制定针对性策略的流程，让你知己知彼。六步为：找到并确认竞品、分解五层要素、拆解竞品阶段、确认自身产品阶段、制定针对性优化计划、总结复盘。", "usage": "操作要点：先分清直接对手即功能相同与间接对手即解决相同需求但方式不同；用五层结构模型逐层拆解竞品战略、功能、交互、界面；判断竞品处于引入、成长、成熟、衰退哪个生命周期阶段并确认自身阶段；基于对比找优势劣势机会威胁，制定功能优化与运营策略，如对手成熟期创新慢时可在细分功能上微创新；最后形成文档与团队同步指导迭代。", "notes": "原文未专门说明注意事项。分析不能只罗列竞品功能，必须结合双方所处阶段制定针对性计划并复盘同步，否则难以指导迭代。", "supp": ["notes"], "kw": ["竞品分析", "五层结构", "生命周期", "微创新", "复盘"], "kp": 20}, {"id": "KB-080", "term": "波特五力模型", "cat": "产品名词", "concept": "用于分析行业竞争格局的模型，指出一个行业的竞争激烈程度和赚钱能力由五种力量共同决定：同业竞争者的威胁、潜在新进入者的威胁、替代品的威胁、供应商的议价能力、购买者的议价能力。做产品选赛道时用它看行业的水深水浅。", "usage": "以新能源汽车为例：消费者可选品牌多议价力强、电池供应商技术集中议价力强、现有品牌众多竞争激烈、造车新势力不断涌现、燃油车与公共交通仍是替代品，五力都很强，说明该行业竞争极其激烈、需要巨大投入和差异化。PM选赛道时逐力评估后再决定进入方式。", "notes": "原文未专门说明注意事项。五力需逐项评估，不能只看同业竞争一项就判断行业吸引力。", "supp": ["notes"], "kw": ["波特五力", "竞争格局", "议价能力", "替代品", "行业分析"], "kp": 20}, {"id": "KB-081", "term": "PEST模型", "cat": "产品名词", "concept": "帮你抬头看路、分析宏观大环境的模型，看国家、社会、经济和技术大趋势会不会影响产品或行业。四要素为：政治即政策法律监管变化；经济即GDP增长、利率、收入水平与消费意愿；社会即人口结构、文化观念与生活方式变化；技术即新技术突破与应用。", "usage": "以在线教育为例应用：曾受社会上家长重视教育与技术上网络直播成熟的正面推动，也深刻受政治上双减政策和经济上资本热度变化的影响。PM评估行业时逐项扫描四要素，识别机会与风险变量，如数据安全法、反垄断法、双减政策都可能是巨大影响变量。", "notes": "原文未专门说明注意事项。宏观因素影响可能是决定性的，如政策变化可重塑行业，不能只看产品与市场本身而忽略PEST扫描。", "supp": ["notes"], "kw": ["PEST", "宏观环境", "政策", "经济", "社会", "技术"], "kp": null}, {"id": "KB-082", "term": "Gartner曲线（技术成熟度曲线）", "cat": "产品名词", "concept": "描述一项新技术从诞生到被大众接受通常经历的过山车式心理和炒作周期的模型，帮你判断技术处在哪个阶段、是炒作泡沫还是真的机会。五阶段为：技术萌芽期、期望膨胀期、泡沫破裂谷底期、稳步爬升复苏期、实质生产高峰期。", "usage": "使用时先定位阶段再决策：萌芽期关注概念验证；膨胀期媒体市场过度炒作期望达顶峰；谷底期技术未达预期热潮消退；复苏期技术被务实改良价值被认可；高峰期技术成熟被广泛采纳成主流。区块链、元宇宙、AI大模型都曾或正在经历这样的曲线。", "notes": "了解它能帮助在投资或入场时保持理性，避免在期望膨胀期跟风追高，或在谷底期错失真正的机会。", "supp": [], "kw": ["Gartner曲线", "技术成熟度", "期望膨胀期", "泡沫破裂", "炒作周期"], "kp": null}, {"id": "KB-083", "term": "康波周期", "cat": "产品名词", "concept": "一个长达50-60年的经济大周期理论，认为世界经济会经历复苏、繁荣、衰退、萧条四个阶段的循环。它提醒我们个人奋斗固然重要，也要考虑历史的进程，大的时代浪潮如互联网革命、新能源革命决定了行业和个人的发展上限。", "usage": "以20世纪90年代开启的互联网信息革命为例，其带来长达二三十年繁荣期，无数互联网公司和从业者乘上浪潮。了解康波周期可思考下一个技术革命浪潮可能是什么如人工智能、生物科技，从而提前布局职业或事业。", "notes": "原文未专门说明注意事项。运用该理论是做长周期趋势思考，不应把周期判断当作确定预测来决定具体短期行动。", "supp": ["notes"], "kw": ["康波周期", "经济周期", "技术革命", "长期趋势"], "kp": null}, {"id": "KB-084", "term": "产业链分析", "cat": "产品名词", "concept": "把一个行业从原材料到最终卖到消费者手里的完整链条拆解开，看链条上有哪些环节、公司处在哪个位置、哪个环节利润高话语权强，目的是找到优势和潜在突破机会。组成分上游即提供原材料核心零部件或技术，中游即产品制造组装或服务集成，下游即负责销售和服务的渠道。", "usage": "以智能手机为例：上游芯片、高端屏幕厂商利润率高技术壁垒高；中游品牌商竞争最激烈但品牌价值高；下游渠道商利润较薄但流量大。新品牌进入需分析能否在上游拿到好元器件、在下游有没有强势渠道，再决定切入位置。", "notes": "原文未专门说明注意事项。进入一个行业前需把上中下游的利润与话语权分布摸清，不要只看自身所在环节下判断。", "supp": ["notes"], "kw": ["产业链", "上游", "中游", "下游", "利润分布"], "kp": null}, {"id": "KB-085", "term": "金字塔原理", "cat": "产品名词", "concept": "一种让思考和表达都清晰有说服力的结构化方法，核心心法是结论先行，然后像金字塔一样从上到下展开论证：顶端是核心结论，支撑它的是几个关键论点，每个论点下面又有事实和细节论据支撑，让听者第一时间抓住重点并沿逻辑理解全部论述。", "usage": "产品工作中可从最顶层战略目标开始，一层层推导需要哪些核心功能模块、每个模块下需哪些具体功能，确保设计不偏离核心目标。汇报新产品方案时先给结论如建议启动A项目能抢占20%新市场份额，再依次用市场空白、技术优势、ROI测算三点论据支撑。", "notes": "原文未专门说明注意事项。使用关键是结论先行且下层论点要真正支撑上层结论，不能只摆结论而无事实论据跟进。", "supp": ["notes"], "kw": ["金字塔原理", "结论先行", "结构化表达", "汇报"], "kp": 26}, {"id": "KB-086", "term": "鱼骨图（因果图）", "cat": "产品名词", "concept": "用来深挖问题根本原因的侦探工具。当复杂问题出现时把问题画在右侧作鱼头，向左延伸几根主骨代表几类可能的问题大方向，再在每根主骨上长出小骨即具体可能原因，最终画出所有潜在原因找到症结。主骨类别常用人、机、料、法、环等。", "usage": "应用六步：确立要分析的问题和目标；开脑暴写下所有可能原因；把原因归到几大类别形成主骨；分析圈定最可能的根本原因；针对根本原因制定解决方案；制定行动计划落实人员和时间。如APP新版上线后日活下降10%，可从人即新界面不习惯路径变深、法即重大Bug闪退机型不兼容、环即竞品同期活动等主骨逐项排查。", "notes": "原文未专门说明注意事项。使用时要先穷举并归类原因、再圈定根本原因，不要跳过分析直接凭直觉定原因或急于给方案。", "supp": ["notes"], "kw": ["鱼骨图", "因果图", "根本原因", "问题分析"], "kp": 23}, {"id": "KB-087", "term": "MAIR模型/框架", "cat": "产品名词", "concept": "一套横向挖掘AI产品需求的四步方法论，像在工厂里寻找可自动化环节的侦察兵：先摸清整个生产流程M，再找出哪些环节最依赖老师傅经验和判断A，接着评估这些经验环节有多贵多重要I，最后才寻找能替代的智能机器R。帮助PM系统性找到AI最该下手的地方。", "usage": "以电商为例：M梳理用户下单到客服审核、仓库配货、物流发货全流程；A发现客服审核最依赖人工经验判断地址异常、购买行为异常；I发现该环节占客服总工作量40%、人工判断准确率只有85%、出错会导致损失；R决定引入AI欺诈检测模型辅助客服做初筛。", "notes": "原文未专门说明注意事项。顺序不能颠倒：必须先梳理流程、找脑力环节并评估价值，最后才选AI方案，不要上来就搞机器。", "supp": ["notes"], "kw": ["MAIR", "流程梳理", "脑力劳动", "价值评估", "AI需求挖掘"], "kp": 4}, {"id": "KB-088", "term": "Ops-Core框架", "cat": "产品名词", "concept": "一套纵向、具体实施AI替代的七步实操框架，把模糊的用AI做个事变成可执行的操作SOP。当MAIR找到目标环节后，Ops-Core规定这次行动的目标、输入、计划、风格、提示词、演练与结构搭建，即O定输出、P备输入、S定工作流、C定风格、O写提示词、R模拟测试、E搭建AI结构。", "usage": "以AI审单为例执行：O输出订单风险等级高/中/低及关键疑点列表；P输入订单信息加黑名单数据库；S工作流为获取订单、AI评分、高风险转人工低风险自动通过；C输出结构化列表风格；O撰写反欺诈专家提示词；R用过去1000个真实订单测试与人判断的吻合度；E选大模型API结合RAG接入数据库、用函数调用输出结构化结果。", "notes": "原文未专门说明注意事项。落地前必须经过R模拟测试环节用真实历史数据验证吻合度，不要未经演练直接上线替换人工环节。", "supp": ["notes"], "kw": ["Ops-Core", "AI实施", "工作流", "提示词", "模拟测试"], "kp": 14}, {"id": "KB-089", "term": "CRISPE框架", "cat": "产品名词", "concept": "一个用于结构化撰写提示词的经典框架，像给高水平厨师下五星级订单的万能备忘录，包含六个关键维度让指令更精准可控：C&R能力与角色、I洞察与背景、S任务陈述、P风格与个性、E实验与迭代、R响应格式。", "usage": "以让AI写产品发布新闻稿为例：C&R设定为有10年经验的科技媒体记者；I提供公司即将发布AI办公软件主打高效协作的背景；S明确撰写面向企业IT决策者的新闻稿；P指定专业前瞻有说服力避免过度夸张；E给出先写三个不同切入点标题供选择；R规定新闻稿标准格式含标题导语正文结尾公司简介、字数800左右。", "notes": "原文未专门说明注意事项。不能只给厨师一句给我弄点吃的式模糊指令，角色、背景、任务、风格、迭代空间与格式都应写清。", "supp": ["notes"], "kw": ["CRISPE", "提示词", "结构化指令", "角色设定", "输出格式"], "kp": 1}, {"id": "KB-090", "term": "脑力劳动 (Mental Labor)", "cat": "产品名词", "concept": "指业务流程中需要思考、判断、分析、创作的环节，是AI当前最擅长替代或辅助的对象，也是MAIR等方法核心分析对象。其价值通过难度和占用时长来评估。如甜品店里根据顾客描述设计新蛋糕并估算成本调整配方是脑力劳动，搬面粉送外卖则是体力活。", "usage": "评估时同时看难度与时长：如保险理赔流程中审核医疗单据是否符合理赔条款是典型脑力劳动，难度高需医学和法律知识，且占用资深审核员每天60%工作时间，因此自动化价值非常高。PM据此排序AI替代的优先环节。", "notes": "原文未专门说明注意事项。不要只看难度或只看时长单一维度判断价值，两者都高的环节才是优先目标。", "supp": ["notes"], "kw": ["脑力劳动", "AI替代", "难度", "占用时长", "流程分析"], "kp": 3}, {"id": "KB-091", "term": "RFM模型", "cat": "产品名词", "concept": "一种用三个最能反映客户价值的行为指标给客户贴标签、分层级再精细化运营的模型：R即最近一次消费时间、离现在越近越活跃；F即消费频率、次数越多越忠诚；M即消费金额、总额代表总体价值。像店铺老板特别关照最近刚来、经常来、每次花很多钱的客人。", "usage": "按组合分层运营：VVIP客户R近F高M高，推送新品、专属客服或高价值优惠券；沉睡客户R遥远F低，发送大额唤醒券召回；高潜力客户M高但F低，想办法提升复购率。电商示例中重要价值客户为最近一周购买3次总金额超1000元优先服务，重要唤回客户为之前买很多但最近半年没来推送专享券，潜力客户为刚注册买一次金额高引导加入会员。", "notes": "原文未专门说明注意事项。分层后必须配套差异化策略，不同层级用同一套运营动作就失去了分层的意义。", "supp": ["notes"], "kw": ["RFM", "客户分层", "精细化运营", "复购", "召回"], "kp": null}, {"id": "KB-092", "term": "上瘾模型 / Hook模型", "cat": "产品名词", "concept": "一个揭示好产品让用户忍不住一直用背后心理机制的循环模型，包括四步：触发即外部提醒如红点推送或内部习惯如无聊时打开；行动即执行最简单动作满足渴望如点击红点；多变的酬赏即奖励有变化有悬念如刷视频不知下一条是什么、发动态收到点赞；投入即投入时间金钱情感、因舍不得沉没成本更离不开产品并为下一轮触发埋伏笔。", "usage": "以抖音为例对照：推送通知是触发、手指上滑是行动、看到有趣视频是多变酬赏、观看时长增长甚至创作内容是投入，算法再推荐更合口味内容形成新触发。PM设计留存机制时可逐环节检查触发、行动门槛、酬赏变化与投入沉淀是否齐全。", "notes": "原文点出投入会让用户因舍不得沉没成本而离不开产品。使用该模型时需注意酬赏的多变性是关键，固定不变的奖励难以维持期待。", "supp": [], "kw": ["Hook模型", "上瘾模型", "触发", "多变酬赏", "投入", "留存"], "kp": null}, {"id": "KB-093", "term": "AARRR模型", "cat": "产品名词", "concept": "增长黑客的核心模型，也叫海盗模型，描述用户从接触产品到成为粉丝的完整生命周期五环节：获取即用户从哪来；激活即第一次使用有没有体验到核心价值；留存即会不会过段时间再回来；变现即会不会付费及怎么付费；推荐即愿不愿意推荐给朋友。", "usage": "应用核心在漏斗思维和闭环思维：不仅关注每个环节转化率如次日留存率七日留存率、订阅内购广告等变现方式，更要思考如何让满意用户在变现和留存后自发帮你拉新即推荐，形成自我循环的增长飞轮。获取渠道可包括应用商店、广告、朋友推荐，推荐手段可包括邀请有奖、分享裂变。", "notes": "原文未专门说明注意事项。不能只盯单个环节如只拉新，要把五环节当闭环看，让留存与变现用户反哺获取。", "supp": ["notes"], "kw": ["AARRR", "获取", "激活", "留存", "变现", "推荐"], "kp": null}, {"id": "KB-094", "term": "数据埋点", "cat": "产品名词", "concept": "在产品重要页面、按钮、流程节点上埋入一小段追踪代码，当用户触发这些行为时就记录下来形成数据的过程，是产品安装监控摄像头，这些数据是做分析和优化产品的眼睛。三大类型：代码埋点由工程师手动写、精准灵活但工作量大；可视化埋点通过后台点选配置、方便产品运营操作；无埋点即全埋点早期一次性接入SDK自动采集所有行为、全面但数据量大杂乱。", "usage": "如想知道用户在注册流程哪一步放弃，就在获取验证码、提交注册等按钮上埋点，数据会告诉用户到了哪个环节流失、可能原因如收不到验证码。PM按分析目标选择埋点类型并设计关键节点。", "notes": "选型需权衡：代码埋点工作量大，无埋点数据量大且杂乱。可视化埋点虽方便，也要围绕分析目标配置，不要无目标地堆数据。", "supp": [], "kw": ["数据埋点", "代码埋点", "可视化埋点", "全埋点", "行为数据"], "kp": 24}, {"id": "KB-095", "term": "AHA Moment (惊喜时刻)", "cat": "产品名词", "concept": "用户首次真正get到产品核心价值、发出哇哦这个真好用感叹的神奇瞬间。这个时刻直接决定用户是留下来继续探索还是默默卸载，找到并放大这个时刻是提升留存的核心抓手。如Dropbox用户第一次完成文件同步发现电脑手机文件一致、抖音用户刷到第一个忍不住看完大笑的视频、石墨文档用户第一次与同事在线协同编辑实时看到对方输入。", "usage": "找到它的方法是通过数据分析对比长期留存用户与非留存用户，发现前者在早期是否完成了某些共同的关键行为，再据此引导新用户尽快到达该时刻。", "notes": "原文未专门说明注意事项。寻找AHA时刻必须基于留存与非留存用户的行为对比数据，不能凭主观猜测指定某个瞬间。", "supp": ["notes"], "kw": ["AHA Moment", "惊喜时刻", "核心价值", "留存", "关键行为"], "kp": null}, {"id": "KB-096", "term": "Magic Number (魔法数字)", "cat": "产品名词", "concept": "那些被发现与用户长期留存率高度正相关的关键行为指标。一旦新用户完成这些关键动作，就大概率成为忠实用户，任务是找到这些咒语并引导所有新用户尽快念出它们。原文示例：Twitter关注至少7个人、Facebook注册后10天内添加7个好友、Slack在团队中发送2000条消息。", "usage": "找法是把关键用户行为如添加好友、发布内容、完成某项任务与用户第N日留存率做关联性分析，看哪个行为与高留存强相关，找到后在新手引导中推动用户尽快完成该行为。", "notes": "原文未专门说明注意事项。魔法数字必须来自行为与留存率的关联分析结果，不能照搬其他产品的数字直接套用。", "supp": ["notes"], "kw": ["Magic Number", "魔法数字", "留存率", "关键行为", "关联分析"], "kp": null}, {"id": "KB-097", "term": "AB Test (AB测试)", "cat": "产品名词", "concept": "一个用数据说话的科学决策方法。当不确定两个方案哪个更好时，把用户随机分成A、B两组看到不同方案，收集点击率、转化率等数据，用客观数据决定最终采用哪个方案，而不是凭个人感觉。", "usage": "如电商APP优化加入购物车按钮，方案A红色大按钮与方案B绿色带图标按钮做AB测试，B点击率比A高15%于是全量上线B。在做很多AB测试前需用ICE模型给候选创意排优先级：信心度即多大把握能提升、影响度即预计提升多少关键指标、实现难度即开发花多大力气，按(C+I+E)/3等公式算综合分优先做高分。", "notes": "注意测试前提是随机分组与用客观数据决策；测试资源有限时先用ICE排序，不要把资源平均撒在所有创意上。", "supp": [], "kw": ["AB测试", "随机分组", "数据决策", "ICE模型", "转化率"], "kp": 9}, {"id": "KB-098", "term": "商业画布", "cat": "产品名词", "concept": "一个在纸上或白板上用9个格子快速描绘、讨论和设计商业模式的工具，让复杂商业模式一目了然并检验其逻辑是否自洽。九大模块为客户细分、价值主张、渠道通路、客户关系、收入来源、核心资源、关键业务、重要合作、成本结构。", "usage": "使用时逐格回答：为谁服务、提供什么独特价值、如何接触抵达客户、如何建立维护关系、钱从哪来、拥有什么关键资产、要做哪些最重要的事、需要和谁合作、主要钱花在哪。如简化版微信支付：客户细分是所有微信消费者和商家，价值主张是便捷安全的移动支付体验，收入来源是商家手续费与金融服务利息差，核心资源是微信社交生态、巨大用户基数与金融牌照。", "notes": "原文未专门说明注意事项。使用时要检验九个模块之间逻辑是否自洽，不能只填格子而不看要素间是否互相支撑。", "supp": ["notes"], "kw": ["商业画布", "商业模式", "价值主张", "客户细分", "收入来源"], "kp": null}, {"id": "KB-099", "term": "三级火箭模型", "cat": "产品名词", "concept": "一种层层递进、构建强大商业模式和生态的经典商业增长策略，像发射火箭每级接力助推：第一级流量池用低价甚至免费的高频核心产品吸引海量用户、目标是获取用户而非赚钱；第二级商业化在庞大用户基础上推出高利润增值服务筛选付费用户、目标是赚钱提升ARPU；第三级生态闭环基于用户与商业基础构建更稳固庞大的生态系统、实现可持续盈利和极高粘性。", "usage": "经典示例360安全卫士：一级用免费杀毒软件迅速占领市场获取数亿用户；二级推出360安全浏览器、导航网站通过广告和搜索变现；三级建立基于浏览器的应用商店、游戏平台、金融等生态业务。PM规划增长路径时按先流量、再变现、后生态的顺序设计每一级的核心目标。", "notes": "注意每一级目标不同：第一级核心是获取用户而不是赚钱，若在流量池阶段就急于变现，可能破坏后续递进基础。", "supp": [], "kw": ["三级火箭", "流量池", "商业化", "生态闭环", "ARPU"], "kp": null}, {"id": "KB-100", "term": "变现模式", "cat": "产品名词", "concept": "产品将用户注意力、流量或使用行为转化为收入的具体方法，回答怎么从用户那里收到钱的问题。常见方式包括广告变现、会员订阅、电商销售、直播打赏、金融模型，以及让用户帮你拉新销售给佣金的分销体系。", "usage": "各方式计费与例子：广告按展示CPM、点击CPC、行为CPA或销售分成CPS计费如抖音信息流广告；会员订阅提供分层增值服务或独家内容如视频VIP、办公软件Pro版；电商直接售卖实物或虚拟商品如淘宝；直播打赏平台从虚拟礼物抽成；金融提供信贷保险理财赚息差或服务费如借呗花呗。产品可组合使用，如学习类APP用会员订阅加电商加开屏广告获得多元收入。", "notes": "原文未专门说明注意事项。变现方式可以多元组合，但应与产品形态匹配，不要把所有方式无区别地堆到一个产品上。", "supp": ["notes"], "kw": ["变现模式", "广告变现", "会员订阅", "电商", "分销"], "kp": null}, {"id": "KB-101", "term": "不可能三角", "cat": "产品名词", "concept": "在项目管理、金融政策、商业设计等很多领域，有三个最想要的核心目标往往互相矛盾、互相制约，很难甚至不可能同时完美达成，必须在三者之间取舍权衡。最经典例子是项目管理三角快、好、省：进度快、质量高、成本低三者往往无法兼得。", "usage": "取舍规律：追求快和好代价是高投入即不省；追求省和快往往牺牲质量即不好；追求好和省往往需要很长时间即不快。做决策或规划时明确核心优先级是什么，并接受为此在其他方面做出的妥协。", "notes": "核心注意事项就是不要幻想三者同时完美达成，必须主动取舍并明确优先级，接受妥协的代价。", "supp": [], "kw": ["不可能三角", "快好省", "取舍", "权衡", "项目管理"], "kp": 17}, {"id": "KB-102", "term": "STAR法则", "cat": "产品名词", "concept": "一个在面试、汇报、写简历时清晰有条理讲述个人经历或项目成果的万能沟通框架，避免讲得一团乱麻、突出能力和价值。四要素为S情境即事情背景、T任务即需完成的具体目标或挑战、A行动即你具体做了什么、R结果即行动带来的可量化成果收益或学习。", "usage": "示例：S负责的电商APP新用户首单转化率只有5%低于行业平均8%；T任务是2个月内不增加预算把首单转化率提升到8%；A先分析行为漏斗发现新手引导不清晰、优惠券门槛高，再推动上线新版分步式新手任务并把首单券门槛从满199减20调为满99减10；R两个月后首单转化率从5%提升至9%超目标，新用户30日留存同步提升3个百分点。讲述时重点讲我做了什么，并用数据说结果。", "notes": "行动部分要重点讲我做了什么而不是我们，突出个人能力与思考；结果部分最好能用数据说话，避免只讲过程没有量化成果。", "supp": [], "kw": ["STAR法则", "面试", "汇报", "简历", "量化成果"], "kp": 26}, {"id": "KB-103", "term": "视觉锤", "cat": "产品名词", "concept": "在用户心智中将一个独特的、有冲击力、好记的视觉概念和品牌牢牢钉在一起的工具。品牌口号是语言钉，视觉锤就是把钉子锤进去的那把视觉锤子，让品牌在众多竞争对手中一眼就认出来。常见锤子包括独特的颜色、形状或Logo、形象或符号、包装。", "usage": "示例：可口可乐的经典红色和弧形瓶身轮廓、LV的Monogram老花图案、美团的袋鼠形象和美团黄，都是与用户建立连接的强有力视觉锤。作用是在信息过载时代降低品牌识别成本、占据用户心智、形成持久品牌资产。PM做品牌设计时应选定一个独特视觉概念并与品牌长期绑定。", "notes": "原文未专门说明注意事项。视觉锤贵在独特、好记且长期一致，频繁更换会削弱用户心智中的绑定效果，原文未展开更换规则。", "supp": ["notes"], "kw": ["视觉锤", "品牌识别", "心智", "Logo", "品牌资产"], "kp": null}, {"id": "KB-104", "term": "π型能力系统", "cat": "产品名词", "concept": "个人能力发展模型的升级版。传统T型人才是知识面广的一横加一项专业技能深的一竖；π型人才在T型基础上再发展出第二项突出的专业技能即另一竖，形成类似希腊字母π的结构，让人在职场中更具竞争力和适应性，不易被单一专业波动影响。", "usage": "结构解读：第一横是广泛的通用知识和基础技能如沟通协作、项目管理、商业常识；第一竖深度专业1是核心立身之本如产品策划能力；第二竖深度专业2是差异化竞争优势如数据分析、UI/UX设计、市场增长甚至跨界的技术架构理解。如优秀产品经理既是产品专家，又是数据分析高手或内容运营行家，能提出更综合的解决方案、职业天花板更高。", "notes": "原文未专门说明注意事项。π型的关键是第二竖要达到突出水平，只浅尝辄止不构成第二项专业技能，原文强调的是更具竞争力与适应性的结构。", "supp": ["notes"], "kw": ["π型人才", "T型人才", "专业技能", "差异化", "能力结构"], "kp": null}, {"id": "KB-105", "term": "评测集构建与版本管理", "cat": "补强", "concept": "评测集是给AI产品准备的一套固定考卷，没有它，改提示词、换模型、调检索后只能凭感觉说变好了。大模型输出不稳定、同一问题今天对明天可能错，只有用同一套有代表性的题目反复考，才能分清真进步还是碰巧。原文以小像为例，其评测集从500条滚动扩充到900条，靠持续补入真实问题而非一次性凑数。", "usage": "PM把控三件事：题目从哪来、覆盖够不够、版本能不能比。来源优先取真实高频问题、线上答错的Bad Case及易出错的边界与对抗问题，按场景与难度分层、避免只挑简单题刷高分；每条样本带标准答案或评分要点、场景标签和来源；新旧方案必须在同一冻结集上回归对比，并单独盯住高风险场景的退化。", "notes": "版本纪律：基线要冻结留档，增删题目、改标准答案都要留变更记录并说明原因，禁止边改考卷边宣布进步。还要防止评测题漏进提示词或知识库，变成背题式高分。", "supp": [], "kw": ["评测集", "版本管理", "Bad Case", "回归对比", "基线冻结"], "kp": 10}, {"id": "KB-106", "term": "标注规范与一致性管理", "cat": "补强", "concept": "标注是把人的判断变成模型和评测能用的标准答案。指南含糊，标注员只能凭感觉打标，同一答案有人判对有人判错，后面算出的准确率和幻觉率全是假的，所以标注质量决定评测结论可不可信。原文以小像为例，其标注一致性曾从71%提升到93%，靠规范、培训与质检把个人感觉收敛成统一口径。", "usage": "PM要把控的是把规范立起来：一份可执行标注指南写清判定定义、正例反例和边界案例处理口径；标注、审核、仲裁角色分开、关键分歧不能由标注员自己拍板；新人先试标过关再正式标，过程中按比例抽检并反馈错误类型。指南随线上新问题类型出现要回炉修订并同步版本，旧口径样本按需复标。", "notes": "不要靠多招人堆数量解决一致性问题；分歧要有明确升级路径，不能由标注员自行拍板。指南写完不等于定死，口径变化后需留版本。", "supp": [], "kw": ["标注规范", "一致性", "标注指南", "仲裁", "抽检"], "kp": 10}, {"id": "KB-107", "term": "LLM-as-Judge 与自动评测", "cat": "补强", "concept": "LLM-as-Judge是请一个大模型当裁判，按事先写好的评分量规给另一个模型的回答打分或做两两比较。它重要的原因是规模：人工评测准但慢、贵，版本一多评不过来，自动裁判能把回归评测做到每次发版都跑。原文明确这是下一步要补强的方向，不能说成已经落地的经验。", "usage": "PM把控裁判可不可信：上线前先用人工标注的金标样本校准，看裁判与人工的一致程度，不达标就改量规或换裁判模型；量规和裁判提示词要像代码一样版本化、每次变更都复测；高风险和低置信样本仍留人工复核，自动分只作初筛和趋势监控。", "notes": "要防裁判已知偏差：偏爱更长的回答、偏爱排在前面的答案、偏爱自己同系模型的风格，所以比较时要交换顺序、隐藏来源。绝不能只报一个总分就宣布质量过关；关键与高风险场景仍以人工为准。", "supp": [], "kw": ["LLM-as-Judge", "自动评测", "评分量规", "金标校准", "裁判偏差"], "kp": 10}, {"id": "KB-108", "term": "文档切分与知识库构建", "cat": "补强", "concept": "文档切分是把制度、手册等长文档拆成能被单独检索的小块，再连同来源信息一起存入知识库，它直接决定后面能不能召回对的片段。切得太碎，一条完整规定被割成两半、模型拿到半句话容易答偏；切得太大，无关内容混在一起、相关性被稀释，还会挤占上下文。原文以小像处理约60份制度文档为例，按章节语义切块而非机械等长截断。", "usage": "PM先想清用户会怎么问、文档按什么结构组织再定切分策略；为每块保留文档类型、生效日期、适用地域等元数据，检索时先按时效和适用范围过滤，避免拿过期或不适用条款作答；文档更新时分块与索引同步刷新、失效版本及时下线，并用真实问题持续回测召回是否命中。", "notes": "切分不是纯工程活，而是知识治理的第一道门。不能只上新不管旧，过期文档被错误召回是重点防范的质量风险。", "supp": [], "kw": ["文档切分", "知识库", "元数据", "语义切块", "召回"], "kp": 19}, {"id": "KB-109", "term": "混合检索与重排", "cat": "补强", "concept": "混合检索是同时用多条路径找资料再合并排序：向量检索擅长措辞不同但语义相近的问法，关键词检索擅长精确命中编号、专有名词和制度原文表述，借助假设性文档生成的方法能帮口语化问题对齐书面表达。只押注一条路径总有一类问题会漏召回。原文中小像的链路是多路召回后融合、再重排精选少量结果并给出引用溯源。", "usage": "PM要分清召回和排序是两件事：先用多路召回把候选尽量找全，再用按名次融合的规则消除各路分数口径不一致的问题，最后由重排精挑最相关的少数几条喂给模型生成。要用召回率等指标定位问题出在检索侧还是生成侧，再针对性优化；原文复盘显示问题大多出在检索侧，靠问句改写与混合检索加重排的组合优化才把召回效果明显抬升。", "notes": "需平衡三者：召回是否找全、最终入选片段是否相关、延迟和成本是否可接受。各路分数不可直接相加，必须按名次融合消除量纲差异。", "supp": [], "kw": ["混合检索", "向量检索", "关键词检索", "重排", "RRF融合", "引用溯源"], "kp": 19}, {"id": "KB-110", "term": "Query 改写与多轮对话补全", "cat": "补强", "concept": "Query改写是把用户真实说出口的问题先加工成更适合检索的样子再送去查知识库。用户提问往往口语、很短，还带省略和指代，如先问年假规则接着只说那北京的呢，单独拿去检索根本查不准。改写就是结合上下文把指代对象和省略条件补全、把口头说法换成与制度原文更接近的表达，必要时做同义词扩展，让问题变成能独立理解、独立检索的完整问句。", "usage": "原文中小像在意图识别之后、正式检索之前设有改写环节，单是这一步就贡献了可观的召回提升，改写结果还做了缓存复用以降低重复改写的延迟。PM要设计好该环节在链路中的位置，并准备改写失败时的兜底。", "notes": "改写边界必须守住：只能还原用户原意，不能凭空替用户添加没提过的条件，更不能把问题改成另一个问题。兜底上，改写置信度低时保留原问句一并检索。", "supp": [], "kw": ["Query改写", "多轮对话", "指代补全", "同义词扩展", "召回"], "kp": 19}, {"id": "KB-111", "term": "多智能体编排与任务调度", "cat": "补强", "concept": "单个Agent处理复杂任务时容易上下文过载、步骤出错又无人复核。多智能体编排是把大任务拆给多个分工明确的Agent协作，像虚拟团队：有人拆解、有人执行、有人校验。编排管谁先谁后、哪些能并行、失败如何重试或转交，调度管优先级、批次和资源。原文以构建部署工具为例，用WorkBuddy把需求拆成157+个小任务按批次排期、多个AI会话并行开工，并沉淀14条协作规则。", "usage": "PM价值不在堆Agent数量，而在把不可控的生成过程变成可分工、可验收的流水线：拆解时定清粒度、依赖关系与并行串行边界；执行、校验与汇总职责隔离；每批过质量门禁才合入；PM负责需求定义、框架初稿和结果验收，并权衡并行收益与调用成本、延迟的平衡。", "notes": "要注意调度兜底：批次门禁、失败重试与冲突处理需预先设计，Agent数量多不等于效果好，成本与延迟会随并行上升。", "supp": [], "kw": ["多智能体", "任务编排", "任务调度", "并行", "质量门禁"], "kp": 14}, {"id": "KB-112", "term": "Agent 记忆与上下文管理", "cat": "补强", "concept": "Agent能不能记住事直接决定多轮办事连不连贯。短期记忆装当前任务的目标、已确认条件和刚发生的对话，长期记忆存相对稳定的用户偏好与事实，两者不能混为一谈。上下文窗口有限且按量付费，把全部历史一股脑塞进去既贵又容易被无关信息带偏，全不记又会反复追问用户。原文中小像做Query改写时结合多轮对话补全指代和省略，是短期上下文用对地方的例子。", "usage": "PM要能回答三件事：什么该记、记多久、错了怎么改删。做法上短期任务信息与长期稳定事实分开管；按需检索相关片段而非全量塞入；为过期、冲突与低置信记忆建立修正清理机制。", "notes": "长期记忆要守权限与隐私，敏感信息默认少存、可查可删。不要把两类记忆混管，也不要把全部历史无筛选地塞进上下文。", "supp": [], "kw": ["Agent记忆", "上下文管理", "短期记忆", "长期记忆", "隐私"], "kp": 6}, {"id": "KB-113", "term": "人机协同与审批兜底 HITL", "cat": "补强", "concept": "Agent一旦能动手办事而不只是回答问题，答错的代价就变成办错的代价。人机协同与审批兜底就是按风险给自动化划界：低风险、可撤销的动作让Agent自动完成，高风险、不可逆或低置信的情况必须停下来请人确认或接管。原文以小像二期办事Agent为例，走查资格、填OA请假单、4级审批的链路，关键操作做双重权限校验，并守住8条安全红线，转人工率是其7项跟踪指标之一。", "usage": "PM关键不是要不要人工，而是把介入点设计在动作执行之前，并让用户看得懂要批什么、批错有什么后果。按可逆性与影响面做风险分级决定自动或审批；校验留痕做到权限双重校验、过程可追溯可撤回；转人工入口明确、上下文完整交接。", "notes": "兜底设计得好用户才敢把真业务交给Agent。注意高风险动作必须执行前确认而非事后补救，事后补救对不可逆操作无效。", "supp": [], "kw": ["HITL", "人机协同", "审批兜底", "风险分级", "转人工"], "kp": 8}, {"id": "KB-114", "term": "提示词设计模式", "cat": "补强", "concept": "提示词设计模式是给大模型下指令的几种成熟套路。最常用三种：结构化提示词把角色、任务、约束、输出格式分段写清；Few-shot即少样本，给几个典型问答示例让模型照着学；思维链让模型在复杂判断时先分步推理再给结论。同一个模型提示词写法不同效果能差出一截，很多答错不是模型不行，而是问题没说清、边界没划清。", "usage": "PM把控三件事：按任务复杂度选模式，简单任务别硬套思维链徒增成本；约束要落到可检查处，如限定只基于资料回答、强制标注引用；示例要选典型边界案例而不是随便凑数。改版后用固定问题集验证效果。这套打法也可迁移到与智能体协作场景，如用结构化规格加分批指令提需求、验结果。", "notes": "注意示例贵在典型、优先选边界案例；思维链只给复杂判断用，简单任务使用会徒增成本。", "supp": [], "kw": ["提示词", "结构化提示词", "Few-shot", "思维链", "指令设计"], "kp": 1}, {"id": "KB-115", "term": "提示词版本管理与回归测试", "cat": "补强", "concept": "提示词版本管理与回归测试就是把提示词当代码来管。每次改动留版本号和变更说明，改坏了能回滚到上一版；每次改版也不能只试几个新问题，必须拿一套固定的回归问题集把新旧两版放在一起对比，关键指标不退步才允许上线，最好再小流量灰度。原文说明小像项目里实际做到的是提示词像代码一样版本化管理、改坏可回滚。", "usage": "PM把控变更留痕、效果可归因：版本号、变更说明、改动原因齐全；固定问题集对比新旧版关键指标；小流量灰度先行、异常能快速退回旧版；答错的问题按原因分类归档复盘、沉淀为回归用例，而不是改完就算。", "notes": "风险在于提示词改一句话可能修好一个问题、带坏十个旧场景，没有版本和回归出了问题既回不去也说不清是哪次改动惹的祸。原文提醒可用传统软件SVN代码管理与版本发布经验类比理解，但不等于已在AI项目里用过某个专门的提示词管理平台。", "supp": [], "kw": ["提示词版本", "回归测试", "灰度", "回滚", "变更留痕"], "kp": 1}, {"id": "KB-116", "term": "推理成本测算与优化", "cat": "补强", "concept": "推理成本测算与优化讲的是大模型产品每被调用一次要花多少钱，以及怎样把这笔钱花得更省。传统软件上线后边际成本很低，AI产品不同：用户每问一次系统就要消耗一轮Token和算力，调用量越大账单涨得越快，成本会直接吃掉毛利。很多AI项目不是死在效果不好，而是死在没人算账，用户越多亏得越多。", "usage": "PM在需求评审阶段就要算账并写进需求文档：单次调用消耗多少Token、输入输出各占多少，乘日均调用量和模型单价算月成本与单次成本。降本手段包括按任务难度分级用模型、轻量任务交小模型、能用规则代码解决的环节不调模型、控制上下文长度、缓存高频问答结果。原文中小像用GLM-4-Flash处理轻量任务、GLM-4负责正式生成，再以代码块代替部分模型环节，Token成本降低了30%到45%。", "notes": "成本测算不是上线后的财务收尾，而是需求评审就要过的门槛。降本不能降质，优化后要同步复测准确率与延迟，效果和成本一起验收。", "supp": [], "kw": ["推理成本", "Token成本", "分级用模型", "缓存", "成本优化"], "kp": 15}, {"id": "KB-117", "term": "AI 产品 ROI 测算与定价", "cat": "补强", "concept": "AI产品ROI测算与定价讲两件事：先算清投入产出比判断产品值不值得做，再决定对外销售怎么收费。与传统软件不同，AI产品投入除研发人力外还有持续发生的推理成本及数据、评估等隐性成本；收益也不能只看收入，还要算节省工时、处理量提升和错误减少。原文证据如小像一期上线后每月节省约60个工时，构建部署工具把发布周期从5天缩短到3天、整体提效约40%。", "usage": "PM要把账拆开：投入侧按全周期算全，产出侧换算成可核对的业务数字再汇报；用试点数据确认付费意愿与单位经济模型再定规模推广。定价先选方法：成本加成适合成本结构清晰、差异化不强的工具型产品；价值定价适合能直接帮客户省人或增收的场景按创造价值收费；按量计费适合调用量差异大、用量容易计量的产品。选哪种取决于成本结构、客户付费意愿和竞品锚点。原文类比做硬件时管BOM成本：先拆细每一项成本再谈值不值。", "notes": "不要只算一次性开发费而漏掉持续推理、数据与评估成本，也不要靠拍脑袋定价。原文明确内部工具没有对外售价、只算ROI，定价方法适用于对外商业化产品，不要混为一谈。", "supp": [], "kw": ["ROI", "定价", "成本加成", "价值定价", "按量计费", "单位经济"], "kp": 15}, {"id": "KB-118", "term": "数据合规与隐私保护", "cat": "补强", "concept": "数据合规与隐私保护是把一件事管到底：AI产品用到的数据从哪来、能不能用、用多少、存多久、给谁看，每一步都合法且说得清。它重要是因为AI会放大数据风险：存进知识库的文档、用户在对话里留下的信息都可能被检索、生成再传播出去，一旦越界轻则投诉下线重则承担法律责任。原文提到《个人信息保护法》要求目的明确、最小必要并取得同意，敏感个人信息还要单独同意；《生成式人工智能服务管理暂行办法》关注数据来源合法、内容安全与投诉处理。", "usage": "PM要把合规做进产品而非留给法务兜底：上线前盘点数据来源与用途并分级分类，只收必需字段，敏感数据脱敏，按角色设访问权限，定好留存与删除规则，回答带引用溯源方便核实；与法务、工程共同确认，合规嵌进需求评审。原文以小像处理员工制度与人事数据天然敏感为例，并迁移地铁云桌面、内容版权项目的高数据安全要求经验，原则是合规前置、不上线后补票。", "notes": "注意全周期管理：来源、使用、留存、删除每一步都要有规则可查。敏感信息需单独同意，不能用一般同意覆盖。", "supp": [], "kw": ["数据合规", "隐私保护", "最小必要", "数据脱敏", "分级分类"], "kp": 22}, {"id": "KB-119", "term": "提示注入与越权防护、安全红线体系", "cat": "补强", "concept": "提示注入是有人用话术给模型下套，让它忽略原有规则、说出系统提示，或把没权限的数据套出来；越权是再进一步诱导它去查、去办本不该碰的事。它难防的根源在于模型分不清哪句是系统指令、哪句只是待处理的数据，提示词里写再多不许也可能被狡猾说法绕过去。原文以小像为例，设有8条安全红线，覆盖禁止特殊审批、薪资口径统一、防诈骗提醒等事项，关键操作双重校验。", "usage": "防护要做成分层体系：输入侧识别并拦截可疑指令，检索与工具调用按用户身份做权限隔离、只给最小权限，输出侧再过滤敏感内容才发出去；再往上要有明确的安全红线清单写清绝对禁止办理的事项，关键操作双重权限校验，靠阈值让常见问题直接命中、越权请求提前拦截，全程留痕可审计。PM要把红线、校验与拦截当产品需求来设计验收。", "notes": "不能把安全只丢给模型自觉，也不能只靠提示词里写不许。红线清单命中即拦截，权限坚持最小原则，校验与审计缺一不可。", "supp": [], "kw": ["提示注入", "越权防护", "安全红线", "权限隔离", "双重校验"], "kp": 22}, {"id": "KB-120", "term": "AI 项目的效果不确定性管理", "cat": "补强", "concept": "传统软件是确定性的，功能做完要么通过要么不通过；AI系统是概率型的，同一问题这次答对下次可能答错，效果是一条分布而不是一个点，所以没法承诺百分之百准确，也不能拿一次演示通过当验收通过。效果不确定性管理就是把传统项目管理的确定性管控翻译过来：不承诺单点结果，改管指标、区间和风险。", "usage": "PM做法：先定清指标口径与阈值，如原文中小像立项时定清7项上线指标，用固定评测集量出基线，再把目标拆成可分批验证的阶段目标；用达标率与坏例率管效果；答错问题按原因归档复盘，优先补最高频的那一类。这套打法与构建部署工具把157+个任务批次化交付是同一逻辑：先定规格、分批交付、用数据决定继续还是止损。", "notes": "每阶段要预设止损线：调优多轮仍不达标就降级、转人工兜底或暂停，而不是无限投入。不要报拍脑袋的准确率，接受波动但不接受无边界波动。", "supp": [], "kw": ["不确定性管理", "概率型系统", "止损", "阶段目标", "指标口径"], "kp": 17}, {"id": "KB-121", "term": "AI 质量门禁与灰度发布", "cat": "补强", "concept": "硬件量产要过EVT、DVT、PVT和华为TR6这类里程碑门禁，AI产品同样需要，只是检查内容变了：传统门禁查功能与缺陷，AI门禁还要查效果。质量门禁是在版本进入下一阶段前用事先定好的准入标准和检查单逐项把关，不达标就不放行；灰度发布是放行后先小范围试用，盯住指标再决定扩大还是回滚。原文例：小像上线靠21条评测用例加16条检查单把关、四轮审查修掉28+处问题，构建部署工具靠1049个自动化测试用例让每批代码过多道门禁才合入。", "usage": "PM把控三件事：门禁标准提前定，功能、效果、安全指标与阈值提前定死不能上线当天临时商量；检查覆盖功能、效果与安全，评测用例与上线清单逐项过，重要缺陷复盘后固化为自动检查；处置规则写在前面，区分直接阻断、限期整改和留痕放行，结论与责任留档。灰度阶段同步看回答质量与系统稳定性，分批放量。", "notes": "触发预设红线就用提示词版本化等能力快速回滚到上一稳定版。注意不能临场放水，门禁不达标不放行是纪律而非建议。", "supp": [], "kw": ["质量门禁", "灰度发布", "检查单", "回滚", "准入标准"], "kp": 11}, {"id": "KB-122", "term": "数据飞轮与数据标注体系", "cat": "补强", "concept": "数据飞轮是让产品越用越聪明的一套循环：线上使用产生数据，经过脱敏、筛选和去重，把有价值样本送去标注，变成评测集和训练样本；评测或训练让效果变好，用户更愿意用，又带来更多真实数据。转不起来数据只是一堆日志，转起来才是会增值的资产。标注体系是飞轮里的加工环节，负责把原始问题、答错记录和反馈变成带标准判断的可用样本，标注质量靠规范与一致性治理。原文实践：小像评测集从500条滚动增长到900条，答错问题按四类原因归档复盘，检索侧badcase占71%。", "usage": "PM把控四件事：回流口径与脱敏合规、筛选标准、样本流向，以及用评测验证本轮回流有没有带来提升。筛选优先收高频、答错和边界样本，拒绝无筛选全量喂回；流向要分清哪些进评测、哪些才进训练；按版本追踪每批数据去向和收益，坏数据能追溯、能下线。构建部署工具里每个重要缺陷复盘根因、补测试盲区并固化成自动检查规则，也是同一种回流改进逻辑。", "notes": "原文如实说明：小像目前做到评测集滚动加badcase归档这一层，完整飞轮闭环仍是体系目标和补强方向，不能说成已经完整跑通。汇报时须区分已做到与目标状态。", "supp": [], "kw": ["数据飞轮", "数据标注", "Badcase", "数据回流", "评测集"], "kp": 24}, {"id": "KB-123", "term": "多模态产品设计", "cat": "补强", "concept": "多模态产品设计是让产品同时处理文字、语音、图片、视频等多种输入输出，并把它们组合成一条顺畅的任务链，而不是把功能拼盘端给用户。它重要是因为模态选错模型再强体验也会翻车，如嘈杂环境硬推语音、隐私场景要求外放播报，都会让用户直接放弃。原文明确这是需要补强的方向。", "usage": "PM先按场景定组合：用户在什么环境、手是否空闲、信息用看还是听更高效，再决定哪种模态做主输入、哪种做补充，不为炫技堆砌输入输出；给每种模态留降级路径；还要兼顾无障碍，如字幕、朗读与图片替代文本覆盖不同能力与使用环境。", "notes": "降级兜底要求：识别失败能切回文字、低置信要二次确认，单模态失效不堵死任务。对生成的图片、语音等内容要做审核、溯源与高风险人工复核，不能生成完就直接展示。", "supp": [], "kw": ["多模态", "模态组合", "降级兜底", "无障碍", "内容审核"], "kp": null}, {"id": "KB-124", "term": "端侧 AI 与模型压缩", "cat": "补强", "concept": "端侧AI与模型压缩讲的是把模型放进手机、手表、电视等设备本地运行，并通过量化、蒸馏、剪枝把模型变小变省：量化降低数值精度、蒸馏让小模型学大模型、剪枝删掉冗余结构。它重要是因为端侧的算力、内存、功耗和发热都是硬上限，选型不能只看精度榜单。原文说明这块判断能接上做智能穿戴和电视整机时积累的资源受限与芯片选型经验，属于硬件经验向AI部署的迁移。", "usage": "PM要算清取舍：压缩后精度掉多少、延迟与续航是否达标，同时验收精度、延迟、功耗、发热与内存占用；设计端云协同，高频简单与隐私敏感任务放端侧、复杂任务回云端。量化、蒸馏、剪枝按精度损失与收益组合选用。", "notes": "离线与隐私要求：弱网断网时核心功能仍可用、数据尽量不出设备，敏感数据优先本地处理。不能只按精度选型而忽略端侧硬约束。", "supp": [], "kw": ["端侧AI", "模型压缩", "量化", "蒸馏", "剪枝", "端云协同"], "kp": null}, {"id": "KB-125", "term": "Transformer 与注意力机制（Transformer & Attention）", "cat": "技术术语", "concept": "Transformer 是现在几乎所有大模型的共同地基，GPT 里的 T 指的就是它，由谷歌团队在 2017 年的论文中提出。它最核心的部件叫注意力机制：模型在处理每个词时，会回头看上下文里所有词，并判断哪些词对理解当前词最重要、该给多少权重。正是这个机制，让模型能处理长距离的关联，比如读懂代词指代的是前面哪个人物，也让并行训练成为可能，模型才得以越做越大。", "usage": "PM 不需要会推公式，但要知道两个推论：一是模型的理解来自对上下文的动态加权，所以喂给它的上下文质量直接决定输出质量；二是注意力计算的成本随文本长度快速上升，这正是长文本又慢又贵的底层原因，选型谈成本时绕不开。", "notes": "面试被问「大模型为什么能理解上下文」，答到注意力机制就算到位；做产品则要意识到上下文不是塞得越多越好，无关信息会稀释注意力，这也是上下文工程兴起的原因。", "supp": [], "kw": ["Transformer", "注意力机制", "上下文", "并行训练"], "kp": 0, "batch": "supplement2"}, {"id": "KB-126", "term": "推理模型与测试时计算（Reasoning Model & Test-Time Compute）", "cat": "技术术语", "concept": "推理模型是 2024 年以来大模型最重要的形态变化：普通模型收到问题立刻往外蹦答案，推理模型则会先在内部生成一段较长的思考过程，分步拆解、自我检查，再给出结论，就像人做难题时先打草稿。自 OpenAI 的 o 系列和 DeepSeek-R1 之后，这已成为各家旗舰的标配路线。支撑它的概念叫测试时计算：过去提升模型能力主要靠训练时堆参数和数据，现在多了一条路——在回答时多花算力、多想一会儿，难题上的表现随之提升。", "usage": "应用上 PM 要做分级：数学、逻辑、代码、复杂规划类任务上推理模型，闲聊、改写、分类等轻任务用普通模型；产品上要给用户预期管理，比如展示「思考中」状态、允许调节思考深度，并把思考 Token 计入成本测算，否则账单会失控。", "notes": "代价同样明确：思考过程要消耗大量 Token，响应更慢、成本更高，简单问题上想太多反而容易出错、浪费钱。", "supp": [], "kw": ["推理模型", "测试时计算", "思考过程", "任务分级"], "kp": 18, "batch": "supplement2"}, {"id": "KB-127", "term": "上下文工程（Context Engineering）", "cat": "技术术语", "concept": "上下文工程是 2025 年兴起的说法，被视为提示词工程的升级版。提示词工程管的是「一句话怎么写」，上下文工程管的是「模型在干活的那一刻，到底能看到什么」：系统提示、对话历史、检索来的文档、工具返回结果、长期记忆、其他智能体的中间结论，都算上下文。决定成败的不再是某句咒语写得妙不妙，而是这堆信息选得对不对、排得顺不顺、有没有过期和冲突。", "usage": "做 Agent 和 RAG 产品时，PM 要把上下文当成一个要设计、要评测的产品界面：哪些信息常驻、哪些按需检索、历史如何摘要压缩、工具结果如何裁剪，都要有明确策略并纳入评测。面试里被问「提示词工程过时了吗」，正确答法是它被包含进上下文工程，而不是被取代。", "notes": "上下文塞太少，模型缺信息只能编；塞太多，无关内容稀释注意力、还推高成本和延迟，塞错了更会直接把模型带偏。", "supp": [], "kw": ["上下文工程", "提示词工程", "上下文管理", "信息筛选"], "kp": 6, "batch": "supplement2"}, {"id": "KB-128", "term": "MoE 混合专家架构（Mixture of Experts, MoE）", "cat": "技术术语", "concept": "MoE 即混合专家架构，思路是把一个大模型拆成许多个「专家」子网络，每个词元进来时只挑选其中少数几个最对口的专家来处理，其余专家休息。这样模型的总参数量可以做得很大、知识容量足，但单次计算只动用一小部分参数，推理成本不至于跟着总参数一起爆炸。近年的不少开源旗舰模型都采用了 MoE 路线，它也是「参数规模大」和「调用价格低」能同时成立的重要原因。", "usage": "选型比较时，把总参数、激活参数、价格、延迟四个数放在一起看，才不会被宣传口径误导。", "notes": "PM 要注意两个容易误判的点：一是 MoE 模型显存占用按总参数算，参数再「稀疏」，部署时也要把全部专家装进内存，私有化部署的硬件门槛并不低；二是看模型不能只看总参数，要问清激活参数量，那才是决定单次推理成本和速度的部分。", "supp": [], "kw": ["MoE", "混合专家", "激活参数", "总参数"], "kp": 18, "batch": "supplement2"}, {"id": "KB-129", "term": "小语言模型（Small Language Model, SLM）", "cat": "技术术语", "concept": "小语言模型指参数量明显小于旗舰大模型的一类模型。过去行业默认「越大越聪明」，这两年风向变了：靠更好的训练数据、知识蒸馏和合成数据，小模型在分类、抽取、改写、意图识别等边界清晰的窄任务上，已经能做到够用甚至不输大模型，同时便宜、快、能离线、数据不出设备。手机、车机、智能硬件上的端侧 AI，靠的基本都是小模型。", "usage": "PM 的正确姿势不是纠结「用大还是用小」，而是按任务分工：开放域问答、复杂推理用大模型兜底，高频、简单、格式固定的任务交给小模型，把成本和延迟打下来，这也是推理成本优化里最常用的一招。", "notes": "注意事项是小模型的通用能力边界窄，任务一旦超出它训练覆盖的范围，表现会断崖式下跌，所以要给它设好任务边界和兜底升级机制，答不了就转大模型或人工，别让它硬答。", "supp": [], "kw": ["小语言模型", "SLM", "端侧 AI", "任务分工"], "kp": 18, "batch": "supplement2"}, {"id": "KB-130", "term": "长上下文（Long Context）", "cat": "技术术语", "concept": "长上下文指模型一次能读入的文本量大幅扩展，从早期的几千 Token 发展到如今部分旗舰模型已达百万级 Token，相当于一次把一本书、一个代码仓库或几百页合同全塞给模型。这改变了很多产品的设计方式：以前必须先切分、建向量库才能问答的长文档，现在可以直接整份丢进去提问。", "usage": "PM 的判断框架是：文档量不大、更新不频繁、问题偏整体理解时，长上下文简单直接；文档海量、要精确溯源、成本敏感时，RAG 仍是主力。两者更多是搭配而非替代，常见做法是先检索缩小范围、再把候选全文交给长上下文模型细读。面试被问「有了长上下文 RAG 是不是没用了」，就按这个框架答。", "notes": "但窗口大不等于读得懂：模型对长文本中间部分的注意力往往弱于开头和结尾，关键信息埋在中间容易被漏掉，业内称之为「中间遗忘」；而且输入越长，每次调用的成本和延迟越高。", "supp": [], "kw": ["长上下文", "中间遗忘", "Token", "RAG"], "kp": 0, "batch": "supplement2"}, {"id": "KB-131", "term": "GraphRAG（GraphRAG）", "cat": "技术术语", "concept": "GraphRAG 是微软在 2024 年开源的一种 RAG 增强路线。普通 RAG 按语义相似度捞文本片段，擅长回答「某个点写了什么」，却答不好「这批文档整体讲了哪几条主线」「A 和 B 是什么关系」这类要跨多篇文档归纳的问题。GraphRAG 的做法是先用模型把文档里的实体和关系抽出来建成知识图谱，并对图谱做社区聚类、预生成摘要；提问时既能沿图谱找实体邻居，也能调社区摘要做全局归纳。", "usage": "它适合行业研究、合规审查、人物关系梳理等关系密集、要俯瞰全局的场景。PM 立项前先问一句：用户的问题到底是查点还是看面？查点用普通 RAG 就够，上 GraphRAG 前要算清构建与更新的账。", "notes": "代价是建图要对全量文档跑多轮模型抽取，构建成本和周期明显高于普通向量库，文档频繁更新时图谱维护也麻烦。", "supp": [], "kw": ["GraphRAG", "知识图谱", "社区聚类", "全局归纳"], "kp": 19, "batch": "supplement2"}, {"id": "KB-132", "term": "Agentic RAG（Agentic RAG）", "cat": "技术术语", "concept": "传统 RAG 是一条固定流水线：问题进来，检索一次，拼上下文，生成答案。Agentic RAG 把检索的主动权交给模型本身：模型先判断这个问题要不要检索、该查哪个库，然后看第一轮结果够不够，不够就改写问题再查，甚至分步骤查多个来源，最后自查答案有没有依据再输出。等于把「查资料」从固定工序升级成智能体的一个可反复调用的工具。", "usage": "它对复杂问题、多跳问题（答案要拼两三处信息）的效果明显更好，适合深度问答、企业级助手等场景。PM 落地时要给它设护栏：最大检索轮次、超时与成本上限、每步可观测的日志，并用评测集验证它是不是真的比固定流水线强，而不是为了时髦把简单系统复杂化。", "notes": "代价是链路变长：调用次数、延迟和成本都不可控地涨，还可能陷入反复检索的死循环。", "supp": [], "kw": ["Agentic RAG", "多跳问题", "检索护栏", "智能体"], "kp": 19, "batch": "supplement2"}, {"id": "KB-133", "term": "推理加速与 Prompt 缓存（Inference Acceleration & Prompt Caching）", "cat": "技术术语", "concept": "模型生成答案时是逐词往外蹦的，每生成一个新词，都要回头参考前面所有词的中间计算结果。KV 缓存就是把这些中间结果存下来复用，避免重复计算，是推理能跑得动的基础机制。在此之上，厂商又提供了 Prompt 缓存：多次请求里相同的前缀部分（比如很长的系统提示、固定文档）只算一次，后续命中缓存的读取又快又便宜。另一类常用加速手段是投机解码：先用小模型快速草拟几个词，再让大模型一次性校验，通过的直接采纳。", "usage": "这组技术对 PM 的意义全在成本和体验：把稳定不变的内容放在提示词最前面、会话中尽量别改动前缀，缓存命中率就高；客服、文档问答这类系统提示长、问题短的场景收益最大。", "notes": "谈模型价格时也要问清缓存价和普通价的区别，否则成本测算会系统性偏高。", "supp": [], "kw": ["KV 缓存", "Prompt 缓存", "投机解码", "推理成本"], "kp": 13, "batch": "supplement2"}, {"id": "KB-134", "term": "结构化输出（Structured Outputs）", "cat": "技术术语", "concept": "结构化输出指让模型严格按照预先定义好的格式（通常是 JSON Schema）返回结果：字段名、类型、枚举值、可选项都提前约定，模型不能自由发挥格式。它和函数调用是近亲但分工不同：函数调用解决「模型想调用哪个工具、参数是什么」，结构化输出解决「模型这段回复本身长什么样」。", "usage": "只要模型的输出要被程序接着处理，就该用结构化输出：从简历里抽字段、给工单打标签、生成固定格式的报表数据等，省掉了解析自然语言的脆弱环节。", "notes": "注意事项有三点：一是 Schema 别设计得过于复杂，字段太多太深会拉低内容质量；二是不同厂商对结构化输出的支持程度和严格模式不完全一致，选型时要实测；三是格式对了不代表内容对了，业务校验和异常兜底仍然要做，不能把模型返回的 JSON 当免检产品直接入库。", "supp": [], "kw": ["结构化输出", "JSON Schema", "函数调用", "格式约束"], "kp": 1, "batch": "supplement2"}, {"id": "KB-135", "term": "AI 网关与模型路由（AI Gateway & Model Routing）", "cat": "技术术语", "concept": "当一家公司同时用好几个厂商的模型时，如果每个业务都直连各家接口，密钥、限流、账单、故障切换会一团乱。AI 网关就是夹在业务和模型之间的一层统一入口：对外只提供一个接口，内部负责鉴权、限流、日志、成本统计和失败时自动切换备用模型。模型路由是网关最核心的决策能力：根据任务难度、成本预算、延迟要求和当前可用状态，自动决定这次请求发给哪个模型——简单问题走便宜的小模型，难题才升级到旗舰，某个厂商抖动时自动绕行。", "usage": "PM 视角下，它是把「分级用模型」从口号变成系统能力的关键一层，做成本优化和稳定性时绕不开。", "notes": "注意路由规则本身要可观测、可调整：分错级会直接伤效果，所以要留评测和人工抽检，并给关键业务保留强制指定模型的通道，别让自动路由一刀切。", "supp": [], "kw": ["AI 网关", "模型路由", "分级用模型", "故障切换"], "kp": 25, "batch": "supplement2"}, {"id": "KB-136", "term": "数据合成（Synthetic Data）", "cat": "技术术语", "concept": "数据合成指用模型（通常是更强的模型）批量生成训练或评测数据，而不是全靠人工收集和标注。比如让旗舰模型按给定知识点批量出问答对、改写出不同难度的版本、模拟用户各种刁钻问法，生成的数据再拿去训练小模型或扩充评测集。在真实数据不够、涉及隐私不能用、长尾场景凑不齐样本时，它是现在最主流的补数据手段，配合人工抽检过滤后使用。", "usage": "所以 PM 要把好三道关：生成后必须有过滤和抽检、关键场景保留真实数据做锚点、合成数据的来源和比例要留档可追溯。面试里聊数据体系时，能讲清「合成是补充不是替代、真实数据是地基」，就是加分项。", "notes": "风险同样明显：生成数据可能把原模型的错误和偏见一起复制放大，分布又容易过于整齐划一，模型长期只吃合成数据会出现能力退化。", "supp": [], "kw": ["数据合成", "合成数据", "人工抽检", "真实数据锚点"], "kp": 24, "batch": "supplement2"}, {"id": "KB-137", "term": "DPO 直接偏好优化（Direct Preference Optimization, DPO）", "cat": "技术术语", "concept": "大模型训练的最后一步是对齐，让它说话符合人的偏好。传统做法 RLHF 要先训一个奖励模型，再用强化学习反复试探，流程复杂、训练不稳定。DPO 换了个更直接的思路：准备成对的回答——同一个问题，一个人更喜欢的、一个较差的——直接用这些偏好对去调整模型，让它以后更倾向于生成前者、远离后者，省掉了奖励模型和强化学习环节，训练更简单、更稳定、成本更低，如今已是开源社区做对齐最常用的方法之一。", "usage": "筹备微调项目时，预算和周期可以按「准备偏好数据比训练本身更费工夫」来估。", "notes": "PM 需要懂的是它的燃料：偏好对的质量直接决定对齐效果，标注口径不一致，模型就会学歪；而且 DPO 调的是「倾向」，治不了知识错误，事实性问题还得靠 RAG 和评测。", "supp": [], "kw": ["DPO", "偏好优化", "RLHF", "偏好对"], "kp": 2, "batch": "supplement2"}, {"id": "KB-138", "term": "LoRA 与参数高效微调（LoRA & PEFT）", "cat": "技术术语", "concept": "全参微调要改动模型的全部参数，算力和显存开销大，训完每个场景还要存一份完整模型。LoRA 是参数高效微调（PEFT）里最主流的方法：把原模型冻结不动，只在旁边挂一小组可训练的低秩矩阵，训练时只更新这一小部分。这样显存占用和训练成本大幅下降，产物只是一个很小的适配器文件，同一个基座模型可以挂许多个不同场景的适配器来回切换。", "usage": "它特别适合风格话术、固定分类体系、拒答边界这类「调行为」的微调：教模型学会什么时候该拒答、用什么口吻说话，都是它的典型用法。", "notes": "注意事项：LoRA 的能力上限通常略低于全参微调，给模型灌大量新知识不是它的强项，那更该用 RAG 或继续预训练；另外适配器规模的选择、训练数据的质量对效果影响很大，上线前必须在冻结评测集上和基座模型做对比回归，别凭感觉发布。", "supp": [], "kw": ["LoRA", "PEFT", "参数高效微调", "适配器"], "kp": 2, "batch": "supplement2"}, {"id": "KB-139", "term": "护栏与红队测试（Guardrails & Red Teaming）", "cat": "技术术语", "concept": "护栏指部署在模型输入输出两侧的实时检查组件：用户的问题进来先过一遍，模型的回答出去再过一遍，用分类器、规则和审核模型拦截违规内容、敏感信息和越界请求。它和「安全红线」的分工是：红线是政策清单，写明什么绝对不能做；护栏是执行这套政策的工程组件，负责在运行时真正拦住。红队测试则是攻防演练：组织人（或用自动化工具）专门扮演恶意用户，用越狱话术、注入攻击、套话等各种手段试图让系统犯错，上线前测、版本更新后复测，把防线当靶子打。", "usage": "PM 要把两者都写进需求和验收：护栏的拦截率和误伤率要一起看，拦得太宽会误伤正常用户；红队不能只在上线前做一次，新攻击手法层出不穷，要纳入版本回归。", "notes": "只在提示词里写「请不要违规」不算护栏，那只是自律，不是防线。", "supp": [], "kw": ["护栏", "红队测试", "拦截率", "误伤率"], "kp": 11, "batch": "supplement2"}, {"id": "KB-140", "term": "A2A 协议（Agent2Agent Protocol, A2A）", "cat": "技术术语", "concept": "A2A 是智能体之间互相通信的开放协议，由 Google 在 2025 年推出，后交给 Linux 基金会托管。它解决的问题是：不同团队、不同厂商做的智能体，怎么互相发现对方、说明自己会什么、把任务派过去、再把结果和状态回传回来，有点像给智能体定的「外交礼仪」。它和 MCP 是互补关系，也是面试最爱问的一组对比：MCP 管智能体向下接工具和数据，A2A 管智能体之间平级协作。本知识库已有一条讲「多智能体协作」范式的条目，A2A 补的是协议标准这一层。", "usage": "PM 现阶段对它的正确态度是跟踪而非押注：自家系统内部的智能体协作，用编排框架自己调度通常更可控；只有当你要和外部厂商的智能体互联互通时，A2A 这类标准才真正有价值。", "notes": "选型时问清对方生态是否支持，别为一个用不上的标准增加架构复杂度。", "supp": [], "kw": ["A2A", "智能体协议", "MCP", "互联互通"], "kp": 14, "batch": "supplement2"}, {"id": "KB-141", "term": "原生多模态大模型（Native Multimodal Model）", "cat": "技术术语", "concept": "早期的多模态产品是拼出来的：语音识别转文字、大模型想答案、语音合成念出来，三个模型串成一条流水线，延迟层层叠加，语气、情绪这些信息在转文字时就丢了。原生多模态大模型换了架构：同一个模型直接理解和生成文字、图像、音频、视频，信息在模态之间不丢失。最典型的体感是实时语音对话——能被打断、能听出语气、回应快得像真人聊天，靠的都是原生音频建模。", "usage": "PM 做语音助手、视频理解、图文混合问答时，要先分清用的底座是原生多模态还是拼接方案，两者的延迟、成本结构和效果上限完全不同。", "notes": "注意事项：音频视频的计费通常按时长算，成本模型要重做；语音场景还要处理环境噪声、方言口音和打断逻辑；生成侧的图像视频内容则必须过审核与溯源，能力和合规要一起设计。", "supp": [], "kw": ["原生多模态", "语音对话", "模态融合", "拼接方案"], "kp": 18, "batch": "supplement2"}, {"id": "KB-142", "term": "扩散模型（Diffusion Model）", "cat": "技术术语", "concept": "扩散模型是现在图像和视频生成背后的主流技术路线，ComfyUI 里跑的、文生图与文生视频产品用的，大多是它。它的生成方式很反直觉：先拿一张纯噪声图，然后一步步往下「去噪」，每一步都把画面往「像一句文字描述」的方向修一点，几十步之后噪声就变成了一张完整的图。训练时做的则是反过来的事，让模型学会从不同程度的噪声里还原原图。", "usage": "PM 需要懂的几个可调杠杆：采样步数越多通常越精细但越慢，提示词引导强度决定画面听不听话，随机种子决定同一组参数能否复现同一张图——这些正是 ComfyUI 工作流里那些参数的产品含义。", "notes": "做图像视频产品真正的难点不在生成，而在可控性：人物一致性、构图、画面里的文字渲染、批量品控，选型和验收都要围绕这些点设计，而不是只看样张好不好看。", "supp": [], "kw": ["扩散模型", "去噪", "采样步数", "随机种子"], "kp": null, "batch": "supplement2"}, {"id": "KB-143", "term": "世界模型（World Model）", "cat": "技术术语", "concept": "世界模型指 AI 在内部学到的一个「世界如何运转」的模型：给定当前状态和一个动作，它能预测接下来会发生什么——球抛出去会落在哪、车往左打方向盘画面会怎么变。有了它，智能体就能先在脑子里「预演」几种做法再选最优的，而不是在真实环境里试错。这一方向在 2025 至 2026 年明显升温：视频生成模型被不少人视为世界模拟器的雏形，机器人和自动驾驶领域则在认真探索用它做训练与规划。", "usage": "对 PM 来说，现阶段它主要是认知储备而非落地选项：面试和行业讨论里能讲清「世界模型解决的是预测与预演、和大语言模型的文字预测不是一回事」就足够。", "notes": "真要评估相关产品，先问它预测的是哪类环境、精度和时间跨度如何、拿什么评测，别被「通用世界模型」的宣传口径带跑，它离通用可靠还有明显距离。", "supp": [], "kw": ["世界模型", "预测与预演", "世界模拟器"], "kp": null, "batch": "supplement2"}, {"id": "KB-144", "term": "Computer Use 计算机操作智能体（Computer Use）", "cat": "技术术语", "concept": "Computer Use 指让模型像人一样直接操作电脑界面：截一张屏看懂上面有什么，决定下一步点哪里、输入什么，执行完再截图确认，如此循环，直到把任务办完。2024 年 Anthropic 率先以这个名字推出该能力，此后成为各家智能体的标配方向。它最大的价值是绕开接口：大量老旧系统、内部软件根本没有 API，以前自动化只能靠人工，现在模型能直接「上手」操作。", "usage": "PM 评估这类产品要盯三个数：任务成功率、单步耗时（决定总时长能不能接受）、以及误操作的风险控制。适合它的场景是流程固定、量大、无接口的重复办公操作；指望它替代成熟的 API 集成，成本和可靠性目前都不划算。", "notes": "落地纪律必须硬：先在沙箱或测试环境跑，高风险动作（付款、删除、发送）要人工确认，全程留操作记录可回溯。", "supp": [], "kw": ["Computer Use", "计算机操作", "沙箱", "人工确认"], "kp": 14, "batch": "supplement2"}, {"id": "KB-145", "term": "Deep Research 深度研究（Deep Research）", "cat": "应用工具", "concept": "Deep Research 是 2025 年成型的一类产品形态：你给它一个研究课题，它不立刻回答，而是像分析师一样先列提纲、再多轮上网搜索、打开网页逐篇阅读、发现信息缺口后换关键词继续查，最后综合成一篇带出处引用的长报告，整个过程通常要几分钟到几十分钟。各大 AI 厂商在 2025 年相继推出了同类功能。它和普通 AI 搜索的区别在于深度和自主性：搜索是查一条答一条，它是围绕一个问题做完整的调研项目。", "usage": "PM 做这类功能，体验设计是关键：耗时以分钟计，必须用异步任务加进度展示，不能让用户对着转圈干等；报告必须带可点击核查的引用，否则可信度无从谈起；还要允许用户中途补充方向。", "notes": "成本同样不能忽视，一次深度研究的搜索和阅读调用量远超普通问答，免费额度与付费分层要提前算账。", "supp": [], "kw": ["Deep Research", "深度研究", "异步任务", "引用溯源"], "kp": 20, "batch": "supplement2"}, {"id": "KB-146", "term": "数字人（Digital Human）", "cat": "应用工具", "concept": "数字人是把人物形象（真人复刻或虚拟生成）、语音合成和口型表情驱动打包成的「虚拟人」，能开口说话、做表情，代替真人出镜完成播报和讲解。常见形态有三类：直播型，在直播间循环讲解商品、回答常见问题；播报型，批量生成口播视频，用于新闻、培训、课程；交互型，放在大厅大屏或 App 里当客服和导览，能听问题、做回答。", "usage": "选型时把驱动自然度、并发成本、内容审核一起纳入比较。", "notes": "PM 落地时最容易低估的不是生成效果，而是三件配套事：一是授权合规，形象和声音必须有本人授权，用他人的脸和声线要留书面许可；二是交互型数字人的问答能力其实取决于背后的大模型和知识库，形象只是皮，答非所问照样翻车；三是按现行规定，AI 生成合成内容需要做标识，别在合规上裸奔。", "supp": [], "kw": ["数字人", "形象授权", "口型驱动", "内容标识"], "kp": null, "batch": "supplement2"}, {"id": "KB-147", "term": "AI 编程与 Vibe Coding（AI Coding & Vibe Coding）", "cat": "产品名词", "concept": "Vibe Coding 直译「氛围编程」，由 Andrej Karpathy 在 2025 年提出：人不再逐行写代码，而是用自然语言把想法说清楚，AI 负责生成、修改和调试，人主要做提需求、看结果、验收。Cursor 这类 AI 编程工具就是它的载体。这一年多它快速从「做玩具」走向「做产品」：越来越多团队用它在很短时间内搭出可用的原型甚至正式产品，行业里也开始强调在速度之外补上规范、测试和评审，把氛围编程升级成正经的工程纪律。", "usage": "对 PM 的直接价值是武器升级：自己就能把想法做成可点可试的原型，和研发沟通的成本大幅降低，验证需求的周期从周变成天。面试里聊「AI 如何改变产品工作方式」，这就是最有说服力的例子——讲自己用它做过什么、踩过什么坑，比背概念强得多。", "notes": "但要清醒：AI 生成的代码能跑不等于能上线，安全漏洞、技术债、可维护性都要有人兜底评审。", "supp": [], "kw": ["Vibe Coding", "AI 编程", "原型验证", "技术债"], "kp": null, "batch": "supplement2"}, {"id": "KB-148", "term": "LangGraph 状态图编排框架（LangGraph）", "cat": "应用工具", "concept": "LangGraph 是 LangChain 团队推出的智能体编排框架，专门用来搭建有状态、可循环的 Agent 工作流。它把一个任务流程画成一张图：每个节点是一步操作（调模型、调工具、人工确认），边决定下一步往哪走，流程还能在节点之间回头重试。和一次写死的线性链条不同，它自带状态管理与检查点，长流程跑到一半失败了，能从断点续上，不用从头再来。", "usage": "适合多步骤、有分支、要人工介入的办事型流程；小像就用 Coze + LangGraph 编排 6 大工作流，请假审批这类流程被拆成收集信息、查余额、预填单据、主管确认、提交等节点逐步执行。", "notes": "注意事项：图不是画得越复杂越好，节点和分支一多，调试与排障成本陡增；PM 要先把流程和异常分支在纸上画清楚再让工程建图，并给每个节点定好失败时的去向。", "supp": [], "kw": ["LangGraph", "状态图", "图编排", "工作流编排", "Agent 框架", "检查点"], "kp": 14, "batch": "supplement3"}, {"id": "KB-149", "term": "LangChain 应用开发框架（LangChain）", "cat": "应用工具", "concept": "LangChain 是目前使用最广的大模型应用开发框架之一，它把调模型、拼提示词、接工具、查知识库这些常用动作，封装成可以拼装的组件。它的核心思路是「链」：把多个步骤按顺序串起来，上一步的输出喂给下一步，复杂应用就是一条条链的组合。后来居上的 LangGraph 出自同一团队，专攻有状态的图编排，两者常被放在一起比较和选型。", "usage": "PM 评审技术方案时，听到团队说用 LangChain，重点是问清它承担哪一段：是快速验证的原型，还是要长期维护的生产链路，两种用法对稳定性和可维护性的要求完全不同。", "notes": "注意事项：框架版本迭代快、抽象层多，好处是开发快，代价是排障时要穿透框架看底层调用；不要把「用了框架」当成架构设计本身，流程、兜底和评测仍要自己设计。", "supp": [], "kw": ["LangChain", "开发框架", "链式调用", "组件拼装", "应用开发"], "kp": 14, "batch": "supplement3"}, {"id": "KB-150", "term": "Dify 低代码开发平台（Dify）", "cat": "应用工具", "concept": "Dify 是一个开源的低代码大模型应用开发平台，把提示词编排、知识库、工作流、模型接入都做成可视化界面，不写代码或少写代码就能搭出一个 AI 应用。它和 Coze 属于同一类工具：降低搭建门槛，让产品和运营也能参与调提示词、换模型、改流程。搭好的应用可以直接发布成网页，也可以经接口给其他系统调用，并支持私有化部署。", "usage": "PM 最该拿它做两件事：一是快速搭原型验证场景，几天就能拿真实流程给用户试；二是中小团队的内部工具（制度问答、工单助手）直接用它上线，省去从零开发的周期。", "notes": "注意事项：低代码不等于没门槛，复杂分支、精细权限与异常处理仍可能撞上平台的能力边界；选型时先拿最复杂的那个流程试搭，能跑通再定，别被演示里的简单场景带偏。", "supp": [], "kw": ["Dify", "低代码", "应用开发平台", "可视化编排", "快速原型"], "kp": 14, "batch": "supplement3"}, {"id": "KB-151", "term": "LlamaIndex 数据框架（LlamaIndex）", "cat": "应用工具", "concept": "LlamaIndex 是一个专攻「数据接入」的大模型应用框架，解决的是怎么把企业自己的文档、数据库、接口数据整理好，再喂给模型使用。它提供现成的数据加载、切分、索引和查询组件，是搭 RAG 系统时最常用的工具之一，与 LangChain 是同类竞品。可以把它理解为站在数据一侧的框架：LangChain 更偏流程编排，它更偏让数据变得可检索、可溯源。", "usage": "当团队的痛点是文档格式杂、来源多、更新频繁时，PM 要意识到这属于数据工程问题，这类框架的价值就在这里；评估 RAG 方案时，值得问一句数据接入层是用什么搭的。", "notes": "注意事项：框架只解决管道，解决不了数据质量——源文档本身过期、冲突、没人维护，索引做得再好，答出来的也是错的，知识库的运营责任仍在业务侧。", "supp": [], "kw": ["LlamaIndex", "数据框架", "数据接入", "RAG", "索引构建"], "kp": 19, "batch": "supplement3"}, {"id": "KB-152", "term": "多智能体开发框架（CrewAI & AutoGen）", "cat": "应用工具", "concept": "当一个智能体忙不过来，常见做法是把任务拆给多个各有分工的智能体协作完成，这类框架就是为这种协作提供脚手架的。CrewAI 的思路像组建一个剧组：给每个智能体定角色、目标和工具，再按流程把任务交接下去；AutoGen 出自微软研究团队，更强调智能体之间用对话来协商和推进任务。两者都是开源框架，代表了多智能体落地的两种典型组织方式。", "usage": "PM 听到方案里要上多智能体，先问值不值：任务能不能由单个智能体加工具干完，能干完就别拆；真要拆，先定清每个智能体的职责边界和交接标准，再谈选哪个框架。", "notes": "注意事项：智能体一多，调用次数、延迟和出错点成倍涨，还可能出现互相推诿、循环对话的问题；必须设总轮次上限和人工兜底，并用评测证明多智能体确实比单智能体强。", "supp": [], "kw": ["CrewAI", "AutoGen", "多智能体框架", "角色分工", "智能体协作"], "kp": 14, "batch": "supplement3"}, {"id": "KB-153", "term": "推理部署工具（vLLM & Ollama）", "cat": "应用工具", "concept": "模型训练完只是半成品，要让它对外提供问答服务，还需要一个推理引擎负责高效地跑模型，这类工具干的就是这件事。vLLM 是目前主流的开源推理引擎，靠分页注意力等机制把显存用得很省，能在同样的硬件上同时服务更多用户，多用于正式上线部署。Ollama 则主打简单：在自己电脑上一条命令就能把开源模型跑起来对话，是本地体验和验证模型的常用工具。", "usage": "PM 做私有化部署或成本测算时会碰到它们：同一块显卡能扛多少并发、延迟多少，很大程度上取决于推理引擎；想在本地验证模型效果时，先用 Ollama 把模型拉起来试，比看参数表直观得多。", "notes": "注意事项：推理引擎解决的是跑得快、跑得省，不改变模型本身的能力上限；选型时要把引擎、硬件、并发目标放在一起实测，别拿单用户演示的流畅度去推断上线表现。", "supp": [], "kw": ["vLLM", "Ollama", "推理引擎", "本地部署", "模型服务"], "kp": 13, "batch": "supplement3"}, {"id": "KB-154", "term": "ReAct 推理行动范式（ReAct）", "cat": "技术术语", "concept": "ReAct 是智能体最经典的工作范式，名字来自 Reasoning（推理）加 Acting（行动）：让模型边想边做，而不是一次想完再做。它的循环是三步：先说出当前想法（想），再决定调用哪个工具（做），然后看工具返回的结果（观察），据此想下一步，如此往复直到完成任务。现在绝大多数 Agent 框架的底层循环，都是这个范式的变体。", "usage": "PM 设计 Agent 时，要把这个循环当成产品结构来设计：每一步的思考要不要展示给用户、工具失败时是重试还是换路、循环多少次必须停下来转人工，都要预先定好。", "notes": "注意事项：循环给了模型纠错的机会，也给了它绕圈子的机会——可能反复调同一个工具，或被错误的中间结果带偏；必须设最大步数、留全程日志，出了问题能回放是哪一步想歪的。", "supp": [], "kw": ["ReAct", "推理行动", "思考-行动-观察", "Agent 范式", "工具调用循环"], "kp": 14, "batch": "supplement3"}, {"id": "KB-155", "term": "规划与反思（Planning & Reflection）", "cat": "技术术语", "concept": "规划与反思，是让智能体从「走一步看一步」升级为「先谋后动」的两个机制。规划指动手前先把大任务拆成子任务清单，排出顺序和依赖，做的时候按单推进；反思指做完一步或拿到结果后，先自查对不对、偏没偏，再决定继续、修正还是重来。两者常配合使用：规划管全局路线，反思管每一步的质量。", "usage": "适合长任务和多步骤办事场景：先列出办一件事要查什么、填什么、找谁确认，再逐步执行、每步核对；PM 要决定的是反思的成本花在哪里，关键步骤步步反思，低风险步骤直接过。", "notes": "注意事项：规划和反思都要额外消耗调用次数和时间，任务越简单越不划算；还要防止模型对自己的错误答案「反思」后仍自信通过，关键结论的校验要靠规则和外部数据，不能只靠模型自查。", "supp": [], "kw": ["Planning", "Reflection", "任务规划", "自我反思", "纠错机制"], "kp": 14, "batch": "supplement3"}, {"id": "KB-156", "term": "机器学习总览（Machine Learning）", "cat": "技术术语", "concept": "机器学习是让计算机从数据里自己总结规律、而不是靠人把规则一条条写死的技术总称，深度学习、大模型都是它的分支。按学习方式主要分三类：监督学习用带答案的数据学规律（如拿标注好的工单学分类），无监督学习不给答案、让模型自己找结构（如把用户自动聚成几群），半监督学习介于两者之间，用少量标注带动大量未标注数据。大模型预训练用的自监督，可以看作监督学习的一种特殊形态。", "usage": "PM 判断一个需求该用什么方法时，先分清它属于哪一类：有历史标注数据的多半是监督学习，想从杂乱数据里找规律的属于无监督；分清类别，才知道要准备什么样的数据、怎么定验收指标。", "notes": "注意事项：机器学习的效果上限由数据决定，规律不在数据里，再好的算法也学不出来；立项时先确认数据够不够、标注质量如何，别等模型训完才发现它学的是错误规律。", "supp": [], "kw": ["机器学习", "监督学习", "无监督学习", "半监督学习", "数据规律"], "kp": 0, "batch": "supplement3"}, {"id": "KB-157", "term": "SFT 指令微调（Supervised Fine-Tuning, SFT）", "cat": "技术术语", "concept": "SFT 即监督微调，是大模型训练的第二个阶段：预训练让模型读完海量文本学会语言，SFT 则用人工整理好的「指令—回答」样本，教它听懂指令、按要求做事。样本通常是成对的提问与理想回答，模型拿它们继续训练，学会该怎么答、答成什么格式、用什么口吻。我们日常用的对话模型基本都经过这一关：它决定了模型「会不会做事」，而 RLHF、DPO 决定的是「做得讨不讨人喜欢」。", "usage": "PM 筹备微调项目时，SFT 是最先要过的方案：要固化话术、格式、分类口径这类「照着样例学」的行为，就准备高质量指令数据做 SFT，并先小批量验证数据质量，再扩大规模。", "notes": "注意事项：SFT 的效果天花板就是样本质量，标注口径不一致、答案本身有错，模型会学得一本正经地错；它教的是行为模式，灌新知识的效率低，知识更新仍要靠 RAG。", "supp": [], "kw": ["SFT", "指令微调", "监督微调", "指令数据", "微调阶段"], "kp": 2, "batch": "supplement3"}, {"id": "KB-158", "term": "温度与采样参数（Temperature & Top-p）", "cat": "技术术语", "concept": "模型生成每个词时，面对的是一串候选词和各自的概率，到底挑哪一个，由采样参数说了算，其中最常用的是温度（Temperature）和 Top-p。温度像一个发散旋钮：调低，模型总挑概率最高的词，回答稳定、保守；调高，低概率的词也有机会被选，回答更发散、更有创意，也更容易胡说。Top-p 则是先圈定一个累计概率范围，只在这个小圈子里挑词，圈越小越稳。", "usage": "这是 PM 少数能亲手调的模型参数：制度问答、数据抽取这类要准的场景把温度压低，起名、写文案这类要花样的场景适当调高；同一个模型在不同功能里应该用不同取值，别全局一刀切。", "notes": "注意事项：参数只能调节随机性，治不了知识错误和幻觉，答错了先查检索和提示词，别指望调温度解决；调完必须在评测集上回归，凭手感调参是上线事故的常见来源。", "supp": [], "kw": ["Temperature", "温度", "Top-p", "采样参数", "随机性控制"], "kp": 0, "batch": "supplement3"}, {"id": "KB-159", "term": "Benchmark 基准测试（Benchmark）", "cat": "技术术语", "concept": "Benchmark 是给模型用的标准化考试：一套固定的题目和判分规则，让不同模型在同一把尺子下比出高下，MMLU 等公开排行榜就是它的产物。它测的通常是知识、推理、代码、数学等通用能力，厂商发布新模型时晒的分数，绝大多数来自这类基准。它和企业自建评测集是两回事：基准测的是通用能力上限，自建集测的是在你自己的业务上到底行不行。", "usage": "PM 选型时可以把榜单当入围门槛：先用 Benchmark 筛掉明显不行的，再拿自家真实场景的评测集决选；面试被问「怎么判断一个模型好不好」，答「榜单看下限、业务集定胜负」就是完整的框架。", "notes": "注意事项：榜单分数会被「刷题」污染——题目可能已经混进训练数据，分数虚高；也要警惕只挑对自己有利的榜单来宣传，关键结论永远以自家评测集的实测为准。", "supp": [], "kw": ["Benchmark", "基准测试", "公开榜单", "MMLU", "模型评测"], "kp": 18, "batch": "supplement3"}, {"id": "KB-160", "term": "可观测性与链路追踪（Observability & Tracing）", "cat": "技术术语", "concept": "AI 应用出了问题不能靠猜：可观测性就是给系统装上仪表盘，把每次请求的输入、输出、耗时、成本和中间步骤都记录下来，随时可查。其中链路追踪专管 Agent 和 RAG 这类多步链路：一次提问经过了哪几步检索、调了哪个工具、每步花了多久、哪一步开始出错，都能串成一条链完整回放。LangSmith 这类工具就是专门做这件事的平台，在 LangChain 生态里尤其常见。", "usage": "PM 要把可观测当成上线门槛，而不是事后补课：没有链路记录，Badcase 来了只能干瞪眼；需求阶段就该定清要记录哪些字段、盯哪些指标（失败率、P99 延迟、单次成本），并纳入验收。", "notes": "注意事项：日志里会留存用户的输入和模型的输出，涉及隐私与敏感数据，要做脱敏和留存期限管理；另外监控要设报警阈值，只记录不看，等于没装。", "supp": [], "kw": ["可观测性", "链路追踪", "Tracing", "LangSmith", "日志监控"], "kp": 23, "batch": "supplement3"}];
